function groupState(g, now){
  const cfg = GROUPS[g], c = cycleFor(cfg, now), members = membersOf(g);
  const endOf = d => d.getTime() + 86400000 - 1;
  const first = parseISO(cfg.firstStmt);
  const preFirst = !!first && c.stmt < first;                    // no statement has been billed yet
  const isFirst  = !!first && iso(c.stmt) === cfg.firstStmt;      // the first one sweeps up everything before it
  const st = statementNear(g, c.stmt), pst = statementNear(g, c.prevStmt);
  if(st && st.due) c.due = parseISO(st.due);
  if(pst && pst.due) c.prevDue = parseISO(pst.due);
  const winStart = (preFirst || isFirst) ? -Infinity : endOf(c.prevStmt);
  const winEnd = endOf(c.stmt);

  // Spends add to what you owe; refunds and reversals back to the card take it off.
  let billedAlerts = 0, unbilled = 0, refunds = 0;
  const byCard = {}; members.forEach(m => byCard[m] = 0);
  TX.forEach(t => {
    if(members.indexOf(t.account) === -1) return;
    const amt = t.dir === "out" ? t.amt : -t.amt;
    if(t.dir !== "out" && (preFirst || t.ts > winEnd)) refunds += t.amt;
    if(preFirst || t.ts > winEnd){ unbilled += amt; byCard[t.account] += amt; }
    else if(t.ts > winStart) billedAlerts += amt;
  });
  billedAlerts = Math.max(0, billedAlerts);

  const ov = overrideFor(g, c.stmt);
  const source = ov !== null ? "you" : st ? st.src : "alerts";
  const billed = preFirst ? 0 : ov !== null ? ov : st ? st.amt : billedAlerts;
  const spendIn = (a, b) => TX.reduce((s,t) => s + (members.indexOf(t.account) !== -1 && t.ts > a && t.ts <= b ? (t.dir === "out" ? t.amt : -t.amt) : 0), 0);
  const payIn = (a, b) => EFF_PAYMENTS.reduce((s,p) => s + (p.group === g && p.ts > a && p.ts <= b ? p.amt : 0), 0);

  // What's been paid towards this bill, and anything still unpaid from the one before.
  //  - A statement total (bank's, CRED's or yours) already nets everything paid and owed
  //    before it closed, so only payments after it count.
  //  - Before any statement, or on the first, every payment counts.
  //  - Added up from alerts, it doesn't: payments since the previous statement first clear
  //    that bill; only the rest counts here, and any shortfall is still owed.
  let from, paid, prevUnpaid = 0;
  if(preFirst || ((isFirst) && !st && ov === null)){ from = -Infinity; paid = payIn(-Infinity, Infinity); }
  else if(st || ov !== null){ from = winEnd; paid = payIn(winEnd, Infinity); }
  else {
    from = endOf(c.prevStmt);
    const pp = onDay(c.prevStmt.getFullYear(), c.prevStmt.getMonth() - 1, cfg.stmtDay);
    const prevFirst = !!first && iso(c.prevStmt) === cfg.firstStmt;
    const prevBill = pst ? pst.amt : (!!first && c.prevStmt < first) ? 0
      : Math.max(0, spendIn(prevFirst ? -Infinity : endOf(pp), from) -
                    payIn(prevFirst ? -Infinity : endOf(addDays(pp, cfg.dueAfter)), from));
    const since = payIn(from, Infinity);
    let carry = since - prevBill;
    // alerts miss small reversals and CRED discounts, so a payment within 3% clears it
    if(carry < 0 && since > 0 && -carry <= Math.max(25, 0.03 * prevBill)) carry = 0;
    paid = Math.max(0, carry);
    prevUnpaid = Math.max(0, -carry);
  }

  const toBilled = Math.min(paid, billed);
  const toUnbilled = paid - toBilled;
  const billedLeft = billed - toBilled + prevUnpaid;
  const unbilledLeft = Math.max(0, unbilled - toUnbilled);
  const credit = Math.max(0, toUnbilled - unbilled);
  const dueIn = days(now, prevUnpaid >= 0.5 ? c.prevDue : c.due);

  return {key:g, label:g, cfg, members, c, okey:g + "|" + iso(c.stmt), billed, billedAlerts, source, st,
          minDue: st && st.min ? st.min : null, hasOverride:ov !== null, from, prevUnpaid, refunds,
          toBilled, billedLeft, preFirst, unbilled, byCard, toUnbilled, unbilledLeft, credit, paid,
          owed: billedLeft + unbilledLeft, dueIn,
          state: billedLeft < 0.5 ? "settled" : urgency(dueIn)};
}

function allCards(){
  const now = sod(new Date());
  const rank = s => ({urgent:0, soon:1, later:2, settled:3})[s];
  return openGroups().map(g => groupState(g, now))
    .sort((a,b) => rank(a.state) - rank(b.state) || a.dueIn - b.dueIn);
}


/* ---------------- server ----------------
   The data layer (rn/src/store.js) answers serverCall("getData") and serverCall("saveSettings"). The engine never
   touches the page: it tells the app what changed through hook(name, …). */
function serverCall(name, arg){ return window.MONEY.serverCall(name, arg); }
const hook = (name, ...a) => { try{ const f = window.UI && window.UI[name]; if(typeof f === "function") return f(...a); }catch(e){ console.error(e); } };
let FEED = {cls:"idle", txt:"Starting up"}, BANNER = null, SAVE_MSG = "", DATA_IN = false;
function setFeed(cls, txt){ FEED = {cls, txt}; hook("feed", FEED); }

/* Your own edits (Phase B): a note per transaction (its category, "spent for someone else", "a friend paying me
   back", a note) and payee rules, kept in their own tables (txn_notes, payee_rules). A note beats a rule, and a rule
   beats the Sheet. NOTES_OK is false until those tables exist; until then rules and "paid back" live in the saved
   settings as before, and the extra choices are hidden because they couldn't be saved. */
let NOTES = {}, NOTES_OK = false;
const noteOf = id => NOTES[id] || null;

function applySettings(s){
  DATA_IN = true;
  if(typeof s.ob === "number") settings.ob = s.ob;
  if(typeof s.obAt === "number") settings.obAt = s.obAt;
  if(typeof s.hob === "number") settings.hob = s.hob;
  if(typeof s.hobAt === "number") settings.hobAt = s.hobAt;
  if(typeof s.inc === "number") settings.inc = s.inc;
  if(typeof s.payDay === "number") settings.payDay = s.payDay;
  if(typeof s.payDayV === "number") settings.payDayV = s.payDayV;
  if(typeof s.buffer === "number") settings.buffer = s.buffer;
  if(typeof s.joined === "string") settings.joined = s.joined;
  if(typeof s.migrated === "string" && s.migrated) settings.migrated = s.migrated;
  if(Array.isArray(s.goals)) goals = s.goals;
  if(Array.isArray(s.contribs)) contribs = s.contribs;
  if(s.payAssign && typeof s.payAssign === "object") payAssign = s.payAssign;
  if(Array.isArray(s.manual)) manual = s.manual;
  if(s.overrides && typeof s.overrides === "object") overrides = s.overrides;
  if(Array.isArray(s.payments)) payments = s.payments;
  if(s.catRules && typeof s.catRules === "object") catRules = s.catRules;
  if(s.cfg && typeof s.cfg === "object") applyCfg(s.cfg);
  if(s.profile && typeof s.profile === "object") applyProfile(s.profile);
}
/** The two edit tables, when the data layer could read them. */
function applyNotes(data){
  NOTES_OK = !!(data && data.notesOk);
  if(!NOTES_OK) return;
  NOTES = data.notes && typeof data.notes === "object" ? data.notes : {};
  if(data.payeeRules && typeof data.payeeRules === "object") catRules = data.payeeRules;
}

/** Takes in what getData() returned. The server runs this too (supabase/functions/_shared/engine.gen.js), so the
    widget and the 9 PM summary show exactly what the app shows. Returns whether the settings need saving. */
function ingest(data){
  if(data.settings && data.settings.profile) applyProfile(data.settings.profile);   // which cards are closed, before the rows are read
  TX = takeTx(data.tx);
  const v4 = Array.isArray(data.events);
  const evSeen = {};
  EVENTS = v4 ? data.events.filter(e => e && e.id && !evSeen[e.id] && (evSeen[e.id] = true)) : [];
  lastRun = data.lastRun || null; lastFetch = Date.now();
  const s = data.settings || {};
  applySettings(s);
  applyNotes(data);
  buildMonths();
  return !s.seeded;
}

async function load(){
  if(fetching) return;
  fetching = true; hook("busy", true);
  setFeed("warn", TX.length ? "Checking for new emails…" : "Loading…");
  try{
    const data = await serverCall("getData");
    if(!data || data.ok !== true) throw new Error("The data didn't load properly.");
    const needsSave = ingest(data);
    BANNER = null;
    cacheLocal(); render();
    if(needsSave) pushSettings();
    setFeed("", TX.length ? "Emails checked " + ago(lastRun) : "Connected. No transactions yet.");
  }catch(e){
    BANNER = {title:"Showing the last figures that loaded", text:String(e && e.message || e)};
    setFeed("warn", lastFetch ? "Last loaded " + ago(lastFetch) : "Not loaded yet");
    hook("render");
  }finally{ fetching = false; hook("busy", false); }
}
/** Refresh: ask the collector to read Gmail now, then load what it found. */
function refresh(){
  if(fetching) return Promise.resolve();
  const ask = window.MONEY && MONEY.refreshNow ? MONEY.refreshNow() : Promise.resolve();
  return Promise.resolve(ask).catch(() => {}).finally(load);
}

function cacheLocal(){ lsSet(CACHE_KEY, JSON.stringify({tx:TX, events:EVENTS, settings, manual, payments, overrides, catRules, goals, contribs, payAssign, cfg, profile:PROFILE, lastRun, at:lastFetch, notes:NOTES, notesOk:NOTES_OK})); }

let saveTimer = null;
const saveMsg = t => { SAVE_MSG = t; hook("saved", t); };
function queueSave(){ clearTimeout(saveTimer); saveMsg("Saving…"); saveTimer = setTimeout(pushSettings, 700); }
async function pushSettings(){
  cacheLocal();
  try{
    const out = await serverCall("saveSettings",
      {ob:settings.ob, obAt:settings.obAt, hob:settings.hob, hobAt:settings.hobAt, inc:settings.inc, payDay:settings.payDay, payDayV:settings.payDayV, buffer:settings.buffer, joined:settings.joined || "",
       migrated:settings.migrated || "", manual, payments, overrides, catRules, goals, contribs, payAssign, cfg, profile:PROFILE, seeded:true});
    saveMsg(out && out.ok ? "Saved." : out && out.conflict ? "Changed on another device, so this shows the latest." : "Saved on this device only.");
  }catch(e){ saveMsg("Saved on this device; it'll sync when the connection is back."); }
}

/* ---------------- engine: balance, card payments, pay cycle, goals ---------------- */
const DAY = 86400000;
const fmtY = d => fmt(d) + " " + d.getFullYear();
/* Your bank accounts (BANKS, from your profile). Safe to spend, where you stand and the balance history use them
   together; each has its own balance you set. A credit card from the same bank is not one. */
const bankOf = t => BANKS.find(b => b.re.test(t.account || "")) || null;
const isBank = t => !!bankOf(t);

/** Money you moved between your own two accounts: a debit from one and a credit of the same amount (₹1 either way)
    to the other, the credit from an hour before to 2 days after. Neither side is spending or income. */
function ownTransfers(){
  const out = new Set(), ins = TX.filter(t => isBank(t) && t.dir === "in");
  TX.filter(t => isBank(t) && t.dir === "out").sort((a, b) => a.ts - b.ts).forEach(t => {
    const from = bankOf(t);
    const m = ins.filter(c => !out.has(c.id) && bankOf(c) !== from && Math.abs(c.amt - t.amt) <= 1 &&
                              c.ts - t.ts >= -3600000 && c.ts - t.ts <= 2 * DAY)
      .sort((a, b) => Math.abs(a.ts - t.ts) - Math.abs(b.ts - t.ts))[0];
    if(m){ out.add(t.id); out.add(m.id); }
  });
  return out;
}
const PAY_RE = /\b(credit ?card|card ?bill|cc ?(bill|pay(ment)?)|ccpay|cred( ?club)?|dreamplug|billdesk|bbps|sbi ?card|sbicard|icici ?(bank ?)?(credit ?)?card|amazon ?pay ?icici|hdfc ?(bank ?)?(credit ?)?card|hdfccard)\b/i;
/** Accounts a debit's text could be paying: the first of your profile's payText that it matches (a bank's name
    alone can't tell two of its cards apart), otherwise each card's issuer. */
function groupsFromText(txt){
  const byIssuer = i => Object.keys(GROUPS).filter(k => GROUPS[k].issuer.toLowerCase() === String(i).toLowerCase());
  for(const x of PAY_TEXT) if(x.re.test(txt)) return Array.isArray(x.groups) ? x.groups.filter(g => GROUPS[g]) : byIssuer(x.issuer);
  if(!PAY_TEXT.length) for(const i of new Set(Object.keys(GROUPS).map(k => GROUPS[k].issuer).filter(Boolean)))
    if(new RegExp("\\b" + reEsc(i), "i").test(txt)) return byIssuer(i);
  return Object.keys(GROUPS);
}

/** When a hand-added entry happened: the moment you added it if that was the same day, otherwise noon that day. */
const manualWhen = m => { if(m.ts) return m.ts; const [y, mo] = String(m.ym).split("-"); return new Date(+y, +mo - 1, m.d, 12).getTime(); };
/** Money in or out of a bank account that you added by hand (the alerts missed it, e.g. a salary credit with no
    email), in the same shape as an alert, so balances and the salary see it. */
function manualBankTx(){
  return manual.filter(m => bankByKey(m.acct)).map(m => ({id:m.id, ts:manualWhen(m), amt:m.amt,
    dir:m.dir === "in" ? "in" : "out", account:bankByKey(m.acct).full + " (added by you)",
    desc:m.t, raw:"", cat:m.c, man:true}));
}
const bankTx = () => TX.concat(manualBankTx());
/** Each account's balance = what you last typed for it, plus every alert (and entry you added) after that moment. */
function accountBalance(k){
  const b = bankByKey(k), ob = settings[b.ob];
  if(typeof ob !== "number") return {key:b.key, name:b.name, full:b.full, set:false, bal:null, ob:null, since:null, inn:0, out:0};
  const from = settings[b.at] || 0;
  let inn = 0, out = 0;
  bankTx().forEach(t => { if(bankOf(t) !== b || t.ts <= from) return; if(t.dir === "in") inn += t.amt; else out += t.amt; });
  return {key:b.key, name:b.name, full:b.full, set:true, bal:ob + inn - out, ob, since:from, inn, out};
}
/** Both accounts together. Null until at least one balance is set. `since` is the oldest of the dates you set
    them (for "last checked"); `missing` lists the accounts you haven't set yet (they count as ₹0 until you do). */
function bankBalance(){
  const parts = BANKS.map(b => accountBalance(b.key)), set = parts.filter(p => p.set);
  if(!set.length) return null;
  return {bal:sumOf(set, p => p.bal), inn:sumOf(set, p => p.inn), out:sumOf(set, p => p.out),
          since:Math.min.apply(null, set.map(p => p.since || 0)), parts, missing:parts.filter(p => !p.set).map(p => p.name)};
}
/** The day-by-day start: each account's balance as you set it, undone back to `start` (see balanceHistory). */

/** Your bank balance (both accounts) at the end of each day, worked out from the balance you last entered: forwards with every
    credit and debit since, backwards by undoing the ones before it. So it's only as complete as the alerts are.
    Returns {pts:[{d, bal}] (oldest first, one a day up to today), marks:[{d, kind, amt, title}], set, now}; marks are
    salaries in, card bills paid and the day you set the balance. */
function balanceHistory(){
  const b = bankBalance(); if(!b) return null;
  const set = b.parts.filter(p => p.set), sinceOf = new Map(set.map(p => [BANKS.find(x => x.key === p.key), p.since]));
  const ax = bankTx().filter(t => sinceOf.has(bankOf(t))).sort((x, y) => x.ts - y.ts);
  const signed = t => t.dir === "in" ? t.amt : -t.amt;
  const today = sod(new Date()), first = ax.length ? sod(new Date(ax[0].ts)) : today;
  const start = new Date(Math.max(first.getTime(), addDays(today, -400).getTime()));
  // the balance just before the start: the ones you set, with everything between them undone or added
  let v = sumOf(set, p => p.ob);
  ax.forEach(t => { const since = sinceOf.get(bankOf(t));
    if(t.ts > since && t.ts < start.getTime()) v += signed(t); else if(t.ts <= since && t.ts >= start.getTime()) v -= signed(t); });
  const pts = [], marks = [];
  let i = 0;
  while(i < ax.length && ax[i].ts < start.getTime()) i++;
  for(let d = start; d <= today; d = addDays(d, 1)){
    const end = addDays(d, 1).getTime();
    for(; i < ax.length && ax[i].ts < end; i++){
      const t = ax[i]; v += signed(t);
      if(SELF_TX.has(t.id)) continue;
      if(t.dir === "in" && (t.cat === "Salary" || SALARY_RE.test((t.desc || "") + " " + (t.raw || "")) || (settings.inc && t.amt >= 0.7 * settings.inc)))
        marks.push({d, kind:"salary", amt:t.amt, title:"Salary"});
      else if(t.dir === "out" && withRules(t).cat === "Card payment") marks.push({d, kind:"card", amt:-t.amt, title:"Card bill paid"});
    }
    pts.push({d, bal:v});
  }
  set.forEach(p => { if(p.since) marks.push({d:sod(new Date(p.since)), kind:"set", amt:p.ob, title:"You set the " + p.name + " balance"}); });
  return {pts, marks, now:b.bal, set:b.since ? new Date(b.since) : null, parts:b.parts, missing:b.missing};
}
/** The biggest credits and debits in your bank accounts between two days (for the balance history); money moved
    between your own accounts is left out. */
function bigMoves(from, to, n){
  return TX.filter(t => isBank(t) && !SELF_TX.has(t.id) && t.ts >= from.getTime() && t.ts < addDays(to, 1).getTime())
    .map(t => Object.assign({}, withRules(t), {signed:t.dir === "in" ? t.amt : -t.amt}))
    .sort((x, y) => Math.abs(y.signed) - Math.abs(x.signed)).slice(0, n || 6);
}

function looksLikeCardPayment(t){
  if(!isBank(t) || t.dir !== "out" || SELF_TX.has(t.id)) return false;
  const a = payAssign[t.id];
  if(a === "none") return false;
  if(a) return true;
  const r = catRules[ruleKey(t.desc)];
  if(r === "Card payment") return true;
  if(r && r !== "Cash & transfers") return false;      // you've said it's something else
  return PAY_RE.test((t.desc || "") + " " + (t.raw || ""));
}

/**
 * Payment confirmations — CRED's "payment was successful" and a bank's "payment received" —
 * name the card, so they settle which account a payment went to. CRED's and the bank's emails
 * about the same payment are merged (two CRED emails are two payments). Each is then tied to
 * the bank debit that paid it: a little under what reached the card (CRED knocks off up to
 * ~0.5%; 2% or ₹25 allowed), and either a bill-payment debit from the last 3 days or any debit
 * within 10 minutes. respectNone=false also offers debits you marked "not a card payment".
 */
function confirmations(respectNone){
  const confs = [];
  // A card you don't track here still gets its debit claimed, so it isn't guessed onto yours.
  EVENTS.filter(e => e.type === "payment").sort((a,b) => a.ts - b.ts).forEach(e => {
    const g = GROUP_OF_LAST4[e.last4] || "other:" + e.last4;
    const dup = confs.find(c => c.group === g && c.srcs.indexOf(e.src) === -1 &&
                                Math.abs(c.amt - e.amt) <= 1 && Math.abs(c.ts - e.ts) <= 3 * DAY);
    if(dup){ dup.srcs.push(e.src); return; }
    confs.push({group:g, amt:e.amt, ts:e.ts, srcs:[e.src], last4:e.last4, tx:null});
  });
  const taken = {};
  const debits = TX.filter(t => isBank(t) && t.dir === "out" && !SELF_TX.has(t.id));
  confs.forEach(c => {
    let best = null;
    debits.forEach(t => {
      if(taken[t.id] || (respectNone && payAssign[t.id] === "none")) return;
      const gap = c.amt - t.amt, dt = c.ts - t.ts;
      if(gap < -1 || gap > Math.max(25, 0.02 * c.amt)) return;
      const billish = PAY_RE.test((t.desc || "") + " " + (t.raw || ""));
      if(billish ? (dt < -2 * 3600000 || dt > 3 * DAY) : Math.abs(dt) > 10 * 60000) return;
      const score = Math.abs(dt) + (billish ? 0 : DAY);
      if(!best || score < best.score) best = {t, score};
    });
    if(best){ taken[best.t.id] = true; c.tx = best.t; }
  });
  return confs;
}

/**
 * Every card payment, strongest evidence first:
 *  1. Confirmation emails, each tied to its bank debit where there is one. These set the card
 *     and the amount the card actually got (₹17,419.70 credited for ₹17,365.70 debited).
 *  2. Payments you typed in, unless 1 already covers them.
 *  3. Bank debits that look like bill payments but have no confirmation: your pick, then the
 *     bank named in the text, then the amount fitting one account's bill (statement, minimum,
 *     or everything owed), then the only account with a bill outstanding.
 * Anything still unclear is left for you to assign with one tap.
 */
function resolvePayments(){
  SELF_TX = ownTransfers();
  const now = sod(new Date());
  const byTx = {}, unresolved = [], detail = {};
  EFF_PAYMENTS = [];

  confirmations(true).forEach(c => {
    const t = c.tx;
    if(!GROUPS[c.group]){
      if(t){ byTx[t.id] = null; detail[t.id] = {confirmed:true, other:c.last4, srcs:c.srcs, saved:0}; }
      return;
    }
    EFF_PAYMENTS.push({id:"conf-" + c.group + "-" + c.ts, group:c.group, ts:t ? t.ts : c.ts, amt:c.amt,
      kind:"confirmed", srcs:c.srcs, txId:t ? t.id : null, debit:t ? t.amt : null,
      saved:t ? Math.max(0, Math.round((c.amt - t.amt) * 100) / 100) : 0});
    if(t){ byTx[t.id] = c.group; detail[t.id] = {confirmed:true, srcs:c.srcs, saved:Math.max(0, c.amt - t.amt)}; }
  });

  const fits = (amt, x) => x >= 1 && amt >= x * 0.97 - 10 && amt <= x + 10;
  const cands = TX.filter(t => !(t.id in byTx) && looksLikeCardPayment(t)).sort((a,b) => a.ts - b.ts);
  cands.forEach(t => {
    const text = (t.desc || "") + " " + (t.raw || "");
    let g = toGroup(payAssign[t.id]);
    if(!g){
      const named = groupsFromText(text), live = named.filter(k => isOpen(k, t.ts)), pool = live.length ? live : named;
      if(pool.length === 1) g = pool[0];
      else {
        const st = pool.map(k => groupState(k, now));
        const only = f => { const m = st.filter(f); return m.length === 1 ? m[0].key : null; };
        g = only(s => fits(t.amt, s.billedLeft)) || only(s => fits(t.amt, s.billed)) ||
            only(s => s.minDue && fits(t.amt, s.minDue)) || only(s => fits(t.amt, s.owed)) ||
            only(s => s.billedLeft >= 1);
      }
    }
    if(!g){ unresolved.push(t); return; }
    // CRED pays the whole bill for a little less; with no confirmation, assume it did.
    let credited = t.amt;
    if(/\b(cred|dreamplug)/i.test(text)){
      const s = groupState(g, now);
      if(s.billedLeft >= 1 && t.amt < s.billedLeft && fits(t.amt, s.billedLeft)) credited = Math.round(s.billedLeft * 100) / 100;
    }
    byTx[t.id] = g;
    detail[t.id] = {confirmed:false, saved:credited - t.amt};
    const dup = EFF_PAYMENTS.some(q => q.group === g && Math.abs(q.ts - t.ts) <= 3 * DAY &&
                                       (Math.abs(q.amt - t.amt) <= 1 || Math.abs(q.amt - credited) <= 1));
    if(!dup) EFF_PAYMENTS.push({id:"auto-" + t.id, group:g, ts:t.ts, amt:credited, debit:t.amt,
                                saved:credited - t.amt, kind:"inferred", txId:t.id});
  });

  // Payments you typed in, unless they repeat one found above. One you split across two cards on
  // the same bill is the same single bill payment, so a set of entries within 3 days that adds up
  // to it is dropped too.
  const mine = payments.map(p => {
    const g = toGroup(p.card);
    return g && p.date ? {id:p.id, group:g, ts:new Date(p.date + "T12:00:00").getTime(), amt:p.amt, kind:"manual"} : null;
  }).filter(Boolean);
  const used = {};
  const same = (a, x) => x && Math.abs(a - x) <= Math.max(10, 0.005 * x);
  EFF_PAYMENTS.slice().forEach(q => {
    const near = mine.filter(m => !used[m.id] && m.group === q.group && Math.abs(m.ts - q.ts) <= 3 * DAY);
    const one = near.find(m => Math.abs(m.amt - q.amt) <= 1 || (q.debit && Math.abs(m.amt - q.debit) <= 1));
    if(one){ used[one.id] = true; return; }
    const sum = near.reduce((s,m) => s + m.amt, 0);
    if(near.length > 1 && (same(sum, q.amt) || same(sum, q.debit))) near.forEach(m => used[m.id] = true);
  });
  mine.forEach(m => { if(!used[m.id]) EFF_PAYMENTS.push(m); });
  PAY_INFO = {byTx, unresolved, detail, candidates:new Set(Object.keys(byTx).concat(unresolved.map(t => t.id)))};

  // money you logged as moved to a goal shouldn't also count as spending
  CONTRIB_TX = new Set();
  contribs.forEach(c => {
    const when = new Date(c.date + "T12:00:00").getTime();
    const m = TX.find(t => isBank(t) && t.dir === "out" && !SELF_TX.has(t.id) && !CONTRIB_TX.has(t.id) && !PAY_INFO.candidates.has(t.id) &&
      Math.abs(t.amt - c.amt) <= 1 && Math.abs(t.ts - when) <= 3 * DAY);
    if(m) CONTRIB_TX.add(m.id);
  });
  matchPlanned();
}

/** The transfers that pay planned items (and, under the salary rule, the family share) are
    already set aside from the salary, so they shouldn't count as spending a second time. Each
    planned amount claims the closest bank debit within 2% (₹50 at least) around its date. */
function matchPlanned(){
  PLANNED_TX = new Map();
  const want = PLANNED.filter(p => !isFamilyItem(p)).map(p => ({name:p.name, amt:p.amt, at:parseISO(p.due).getTime(), lo:7, hi:10}));
  planCycles().forEach(c => {          // each month's split: family, SIP and emergency fund
    const m = monthPlan(c), at = c.p0.getTime();
    [[familyItem(), m.family], ["SIP", m.sip], ["Emergency fund", m.ef]]
      .forEach(([name, amt]) => { if(amt >= 500) want.push({name, amt, at, lo:5, hi:12}); });
  });
  want.sort((a,b) => a.at - b.at).forEach(w => {
    const tol = Math.max(50, 0.02 * w.amt);
    const m = TX.filter(t => isBank(t) && t.dir === "out" && !SELF_TX.has(t.id) && !PLANNED_TX.has(t.id) && !CONTRIB_TX.has(t.id) &&
        !PAY_INFO.candidates.has(t.id) && Math.abs(t.amt - w.amt) <= tol && t.ts >= w.at - w.lo * DAY && t.ts <= w.at + w.hi * DAY)
      .sort((a,b) => Math.abs(a.amt - w.amt) - Math.abs(b.amt - w.amt))[0];
    if(m) PLANNED_TX.set(m.id, w.name);
  });
}

/* Your salary rule (cfg.rule, set under Plan → Salary & fixed payments), from the salary on or after `from`: a share
   to savings (the SIP), one to the emergency fund, one to family, and the rest is yours to spend. The emergency fund
   stops at efCapX × salary; once it's full its share goes to savings, so your spending share stays the same. Goals
   are paid for out of the savings share. With no `from` there is no rule: the planner uses your fixed payments. */
const SALARY_RULE_DEFAULT = {from:"", savings:0, ef:0, family:0, efCapX:6, billsFrom:""};
let SALARY_RULE = Object.assign({}, SALARY_RULE_DEFAULT);
/* Card bills come out of the salary they're paid from (from the salary on or after rule.billsFrom, or always when it's
   empty): each salary's plan takes off every card bill due before the next payday (what's billed, or spent so far on
   a bill that hasn't closed yet, plus card EMIs landing on it), and "Yours to spend" is what's left. So a card spend
   counts once, against the salary that pays its bill, not when you swipe. */
const billsFromSalary = cyc => iso(cyc.p0) >= SALARY_RULE.billsFrom;
const cardsPaidLater = cyc => iso(cyc.p1) >= SALARY_RULE.billsFrom;     // this cycle's card spends are paid from a later salary
/** The card bills a salary pays: each open card's bill due from its payday to the day before the next one. Money you
    paid towards a bill before that payday came from somewhere else (your savings, say), so only what's left of it,
    plus what you've paid on it since payday, comes out of this salary: paying the bill doesn't change it. */
function cardBillsFor(cyc){
  if(!billsFromSalary(cyc)) return [];
  const now = sod(new Date()), lo = cyc.p0.getTime(), hi = cyc.p1.getTime(), out = [];
  const inWin = d => d && d.getTime() >= lo && d.getTime() < hi;
  openGroups().forEach(g => {
    const st = groupState(g, now), c = st.c, cfgG = GROUPS[g], mine = [];
    if(!st.preFirst && inWin(c.due) && st.billed >= 0.5)
      mine.push({key:g, name:cardShort(g), total:st.billed, left:Math.max(0, st.billedLeft - st.prevUnpaid), due:c.due, stmt:c.stmt, billed:true});
    if(inWin(c.nextDue)){
      let amt = st.unbilled;
      SCHEDULED.forEach(t => {                      // card EMIs the bank will put on that statement
        if(!CARD_CFG[t.account] || CARD_CFG[t.account].group !== g) return;
        const cc = cycleFor(cfgG, sod(new Date(t.ts)));
        if(iso(addDays(cc.nextStmt, cfgG.dueAfter)) === iso(c.nextDue)) amt += t.amt;
      });
      if(amt >= 0.5) mine.push({key:g, name:cardShort(g), total:amt, left:Math.max(0, amt - st.toUnbilled), due:c.nextDue, stmt:c.nextStmt, billed:false});
    }
    let paid = sumAmt(EFF_PAYMENTS.filter(x => x.group === g && x.ts >= lo && x.ts < hi));     // paid from this salary
    mine.forEach(b => { const take = Math.min(Math.max(0, b.total - b.left), paid); paid -= take;
      b.amt = b.left + take; b.paid = b.left < 0.5; if(b.amt >= 0.5) out.push(b); });
  });
  return out.sort((a, b) => a.due - b.due);
}       // editable under Plan → Salary & fixed payments
const ruleOn = d => !!SALARY_RULE && !!SALARY_RULE.from && sod(d) >= parseISO(SALARY_RULE.from);
const efGoal = () => goals.find(g => /emergency/i.test(g.name || "")) || null;

/* Payments fixed in advance. Each is set aside from the salary of the pay cycle its date falls in.
   from "pay": off the top, before anything else. from "savings": under the salary rule it comes out
   of the emergency-fund share first, then savings, and only then your spending share; before the
   rule starts there's no split, so it comes off the top too. goal: a goal it pays for instead. */
const PLANNED_DEFAULT = [];
let PLANNED = PLANNED_DEFAULT.slice();                           // editable under Plan → Salary & fixed payments
const plannedIn = cyc => PLANNED.filter(p => { const d = parseISO(p.due); return d >= sod(cyc.p0) && d < sod(cyc.p1); });
const sumAmt = list => list.reduce((s,p) => s + p.amt, 0);
const nextCycle = cyc => ({p0:cyc.p1, p1:payOn(cyc.p1.getFullYear(), cyc.p1.getMonth() + 1)});
const emisFor = g => PLANNED.filter(p => p.goal && p.goal.test(g.name || ""));
const andList = a => a.length < 2 ? a.join("") : a.slice(0, -1).join(", ") + " and " + a[a.length - 1];
/** "₹10,000 to family", "₹15,000 SIP", "the ₹12,500 laptop EMI due 1 Nov" */
function plannedPhrase(p){
  if(/^Money to /.test(p.name)) return money(p.amt) + " " + esc(p.name.replace(/^Money /, ""));
  if(/EMI/.test(p.name)) return "the " + money(p.amt) + " " + esc(p.name.replace(/\s+\d+ of \d+$/, "").replace(/^\w/, c => c.toLowerCase())) + " due " + fmt(parseISO(p.due));
  return money(p.amt) + " " + esc(p.name);
}
/** The fixed payment that is the family share before the salary rule starts: "Money to <family>". */
const familyItem = () => "Money to " + (FAMILY || "family");
const isFamilyItem = p => !!FAMILY && String(p.name).toLowerCase().startsWith(familyItem().toLowerCase());
/** The family share as a title: the profile's family with a capital letter, or "Family". */
const familyTitle = () => FAMILY ? FAMILY.replace(/^\w/, c => c.toUpperCase()) : "Family";
/** The pay cycle a date falls in. */
function cycleAt(d){
  const t = sod(d);
  let p1 = payOn(t.getFullYear(), t.getMonth());
  if(p1 <= t) p1 = payOn(t.getFullYear(), t.getMonth() + 1);
  return {p0:payOn(p1.getFullYear(), p1.getMonth() - 1), p1};
}
/** Pay cycles from the one before your first salary up to one starting within 5 days. */
function planCycles(){
  const out = [], soon = Date.now() + 5 * DAY;
  let c = cycleAt(new Date(firstPayday().getTime() - 3 * DAY));   // first payday may be a day or two early
  for(let i = 0; i < 60 && c.p0.getTime() <= soon; i++){ out.push(c); c = nextCycle(c); }
  return out;
}
function goalSavedBefore(g, when){
  return (g.start || 0) + contribs.filter(c => c.goal === g.id && new Date(c.date + "T12:00:00") < when).reduce((s,c) => s + c.amt, 0);
}

/* Your pay (cfg.offer, set under Plan → Salary & fixed payments): gross a month on a basic, plus an allowance paid in
   full each month (allow). Take-home = gross + allowance − your PF − professional tax (pt; ptFeb in February where
   your state charges more then) − TDS. PF: pf × basic, or at most pfCap for salaries paid from pfCapFrom (0 when you
   opt out). A part month is paid by calendar days. firstPayday: your first salary (before it, the stipend). */
const OFFER_DEFAULT = {gross:0, basic:0, pf:0.12, pt:0, ptFeb:null, allow:0, pfCap:0, pfCapFrom:"", firstPayday:"", stipend:0, v:2};
let OFFER = Object.assign({}, OFFER_DEFAULT);                   // editable under Plan → Salary & fixed payments
/** Your first salary's date (a year ago when it isn't set, so the planner simply starts then). */
function firstPayday(){
  const d = parseISO(OFFER.firstPayday);
  if(d) return d;
  const t = sod(new Date()); return new Date(t.getFullYear() - 1, t.getMonth(), Math.min(28, t.getDate()));
}
/** Your PF on a salary paid on `d`: pf × basic, or the cap (₹0 once you opt out) for salaries paid from pfCapFrom. */
function pfOn(d){
  const full = OFFER.pf * OFFER.basic;
  return d && OFFER.pfCapFrom && iso(d) >= OFFER.pfCapFrom ? Math.min(full, OFFER.pfCap) : full;
}
/** Professional tax for a salary paid on `d`: pt, or ptFeb in February when set. */
const ptOn = d => d && d.getMonth() === 1 && typeof OFFER.ptFeb === "number" ? OFFER.ptFeb : OFFER.pt;
/** A full month's take-home for a salary paid on `d` (before income tax). */
const takeHomeOn = d => Math.round(OFFER.gross + OFFER.allow - pfOn(d) - ptOn(d));
/** The take-home of a regular month from now on (PF as it will be, the usual professional tax). */
function regularTakeHome(){
  const from = parseISO(OFFER.pfCapFrom), now = sod(new Date()), d = from && from > now ? from : now;
  return Math.round(OFFER.gross + OFFER.allow - pfOn(d) - OFFER.pt);
}
/** True when the take-home setting is the app's own figure (not one you typed): each month then gets its exact figure. */
const autoInc = () => settings.inc === regularTakeHome();
/* Your salary and fixed payments, as you set them in the app (saved with your settings as `cfg`).
   cfg = {offer:{gross, basic, pf, pt, ptFeb, allow, pfCap, pfCapFrom, firstPayday, stipend, v},
          rule:{from, savings, ef, family, efCapX, billsFrom},
          planned:[{name, amt, due, from:"pay"|"savings", goal:"laptop"}]}  (goal is a goal's name) */
let cfg = null;
const reEsc = t => String(t).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
function applyCfg(c){
  cfg = c && typeof c === "object" ? c : null;
  const num = (v, d) => typeof v === "number" && isFinite(v) ? v : d;
  const o = (cfg && cfg.offer) || {}, r = (cfg && cfg.rule) || {};
  OFFER = {gross:num(o.gross, OFFER_DEFAULT.gross), basic:num(o.basic, OFFER_DEFAULT.basic), pf:num(o.pf, OFFER_DEFAULT.pf),
           pt:num(o.pt, OFFER_DEFAULT.pt), ptFeb:num(o.ptFeb, OFFER_DEFAULT.ptFeb), allow:num(o.allow, OFFER_DEFAULT.allow), pfCap:num(o.pfCap, OFFER_DEFAULT.pfCap),
           pfCapFrom:/^\d{4}-\d{2}-\d{2}$/.test(o.pfCapFrom || "") ? o.pfCapFrom : OFFER_DEFAULT.pfCapFrom, firstPayday:/^\d{4}-\d{2}-\d{2}$/.test(o.firstPayday || "") ? o.firstPayday : OFFER_DEFAULT.firstPayday,
           stipend:num(o.stipend, OFFER_DEFAULT.stipend), v:num(o.v, cfg && cfg.offer ? 1 : OFFER_DEFAULT.v)};
  SALARY_RULE = {from:/^\d{4}-\d{2}-\d{2}$/.test(r.from || "") ? r.from : SALARY_RULE_DEFAULT.from, savings:num(r.savings, SALARY_RULE_DEFAULT.savings),
                 ef:num(r.ef, SALARY_RULE_DEFAULT.ef), family:num(r.family, SALARY_RULE_DEFAULT.family), efCapX:num(r.efCapX, SALARY_RULE_DEFAULT.efCapX),
                 billsFrom:/^\d{4}-\d{2}-\d{2}$/.test(r.billsFrom || "") ? r.billsFrom : SALARY_RULE_DEFAULT.billsFrom};
  PLANNED = cfg && Array.isArray(cfg.planned)
    ? cfg.planned.filter(p => p && p.name && p.amt > 0 && /^\d{4}-\d{2}-\d{2}$/.test(p.due || ""))
        .map(p => ({name:String(p.name), amt:+p.amt, due:p.due, from:p.from === "savings" ? "savings" : "pay", goal:p.goal ? new RegExp(reEsc(p.goal), "i") : undefined, goalName:p.goal || ""}))
        .sort((a,b) => a.due.localeCompare(b.due))
    : PLANNED_DEFAULT.slice();
}
/** The current values in cfg form (what the editor shows and saves). */
function cfgNow(){
  return {offer:Object.assign({}, OFFER), rule:Object.assign({}, SALARY_RULE),
          planned:PLANNED.map(p => ({name:p.name, amt:Math.round(p.amt * 100) / 100, due:p.due, from:p.from, goal:p.goalName || (p.goal ? p.goal.source.replace(/\\/g, "") : "")}))};
}

/** What a cycle's payday should bring, before the credit shows up. */
function expectedFor(cyc){
  const first = firstPayday(), gap = days(first, cyc.p0);
  if(gap < -5) return {amt:OFFER.stipend, stipend:true};
  if(gap > 5) return {amt:autoInc() ? takeHomeOn(cyc.p0) : settings.inc || 0};
  const mStart = new Date(first.getFullYear(), first.getMonth(), 1), mEnd = new Date(first.getFullYear(), first.getMonth() + 1, 0);
  const tomorrow = new Date(sod(new Date()).getTime() + DAY);
  const joined = /^\d{4}-\d{2}-\d{2}$/.test(settings.joined || "") ? parseISO(settings.joined) : null;
  const join = joined || new Date(Math.max(tomorrow.getTime(), mStart.getTime()));
  // a part month is paid by calendar days: joining on the 16th of a 31-day month pays 16 of 31 (the allowance in full)
  const dim = mEnd.getDate(), before = join <= mStart ? 0 : join > mEnd ? dim : join.getDate() - 1;
  const worked = Math.max(0, Math.min(dim, dim - before)), f = worked / dim;
  const amt = worked ? Math.round((OFFER.gross - pfOn(cyc.p0)) * f + OFFER.allow - ptOn(cyc.p0)) : 0;
  return {amt, partial:true, join, worked, dim, assumed:!joined};
}

/** The pay that started a cycle: the actual credit (either account) if it has arrived (from 5 days before payday
    to 10 after; your employer's NEFT of any size, or another credit of at least 70% of what's
    expected), otherwise what's expected. */
function salaryFor(cyc){
  const exp = expectedFor(cyc), lo = cyc.p0.getTime() - 5 * DAY, hi = cyc.p0.getTime() + 10 * DAY;
  const near = bankTx().filter(t => isBank(t) && t.dir === "in" && !SELF_TX.has(t.id) && t.ts >= lo && t.ts <= hi);
  const fromWork = near.filter(t => (t.man && t.cat === "Salary") || (t.amt >= 1000 && SALARY_RE.test((t.desc || "") + " " + (t.raw || ""))));
  const pool = fromWork.length ? fromWork : near.filter(t => exp.amt && t.amt >= 0.7 * exp.amt);
  const cr = pool.sort((a,b) => b.amt - a.amt)[0];
  if(cr) return {amt:cr.amt, credited:new Date(cr.ts), bank:bankOf(cr).key, exp};
  // No alert for it (banks don't always email a salary credit), but you set your salary account's balance on or after
  // payday: the salary is already in that balance, so it mustn't be added again as still to come.
  const salBank = typeof settings.hob === "number" && BANKS[1] ? BANKS[1] : BANKS[0], setAt = salBank ? settings[salBank.at] || 0 : 0;
  if(salBank && exp.amt && !exp.stipend && setAt >= cyc.p0.getTime() && setAt < cyc.p1.getTime())
    return {amt:exp.amt, credited:new Date(Math.max(cyc.p0.getTime(), Math.min(setAt, Date.now()))), bank:salBank.key, inBalance:true, exp};
  return {amt:exp.amt, credited:null, exp};
}
function payNote(sal){
  if(sal.inBalance) return "in the balance you set";
  if(sal.credited) return "credited " + fmt(sal.credited);
  const e = sal.exp;
  if(e.partial) return "first salary, " + e.worked + " of " + e.dim + " days" + (e.assumed ? ", if you join " + fmt(e.join) : "");
  return e.stipend ? "stipend, expected" : "expected";
}

/** Splits one salary by the rule. efSaved = what the emergency fund held before it. */
function splitSalary(amt, efSaved){
  const r = SALARY_RULE, cap = r.efCapX * amt;
  const ef = Math.min(r.ef * amt, Math.max(0, cap - efSaved));
  const savings = r.savings * amt + (r.ef * amt - ef);
  const family = r.family * amt;
  return {amt, savings, ef, family, spend:amt - savings - ef - family, cap, efSaved, efFull:ef < 0.5};
}
/** The rule's split for one pay cycle (of `amt`, or the cycle's salary), after the planned payments due in it. */
function splitFor(cyc, amt){
  const g = efGoal();
  const s = splitSalary(typeof amt === "number" ? amt : salaryFor(cyc).amt, g ? goalSavedBefore(g, cyc.p0) : 0);
  const due = plannedIn(cyc);
  let fromShares = sumAmt(due.filter(p => p.from === "savings"));
  const offTop = sumAmt(due.filter(p => p.from !== "savings"));
  const efTake = Math.min(s.ef, fromShares); fromShares -= efTake;
  const savTake = Math.min(s.savings, fromShares); fromShares -= savTake;
  return Object.assign(s, {efRule:s.ef, ef:s.ef - efTake, savings:s.savings - savTake, efTake, savTake,
                           planned:due, spend:s.spend - offTop - fromShares});
}

/* This month's split — what the sliders show. Every pay cycle starts from your rule (before the rule,
   from the fixed plan: "Money to <family>" if you have one, no SIP or emergency fund). Moving a slider
   keeps that month's choice in `overrides` as "plan|<payday>", e.g. {"sal":70000,"family":25000}.
   Fixed payments (an EMI) aren't sliders; they always come out first.
   Changing the salary re-works the rule's shares from it, except the ones you've moved yourself. */
const planKey = cyc => "plan|" + iso(cyc.p0);
/** The salary the planner works on: your first salary until it has started a pay cycle, then this month's. */
function planCycle(){
  const c = payCycle();
  return days(firstPayday(), c.p0) < -5 ? Object.assign(nextCycle(c), {upcoming:true}) : c;
}
/** The salary the Plan screen shows. On its own (PLAN_VIEW null) it moves on to the next salary once this one is in
    and everything it had to send has gone (or after the first 3 days); "cur" / "next" is your pick on the screen.
    Today's figure, reminders and where you stand always use the current one (planCycle). */
let PLAN_VIEW = null;
function planViewAuto(){
  const base = planCycle(); if(base.upcoming) return "cur";
  const mp = monthPlan(base);
  if(!mp.sal.credited) return "cur";
  return stillToSetAside(mp).length === 0 || days(base.p0, sod(new Date())) > 3 ? "next" : "cur";
}
function planCycleView(){
  const base = planCycle(); if(base.upcoming) return base;
  return (PLAN_VIEW || planViewAuto()) === "next" ? Object.assign(nextCycle(base), {ahead:true}) : base;
}
const planEdits = cyc => { const o = overrides[planKey(cyc)]; return o && typeof o === "object" ? o : {}; };
function monthPlan(cyc){
  const o = planEdits(cyc), sal = salaryFor(cyc), rule = ruleOn(cyc.p0);
  // a salary you set before it came in was an estimate: once it's credited the real amount wins
  // (salAt = when you set it; one set after the credit still counts)
  const salSet = typeof o.sal === "number" && !(sal.credited && !(o.salAt > sal.credited.getTime()));
  const amt = salSet ? o.sal : sal.amt;
  const due = plannedIn(cyc), fixed = due.filter(p => !isFamilyItem(p)), fixedTotal = sumAmt(fixed);
  const split = rule ? splitFor(cyc, amt) : null;
  const def = rule ? {family:split.family, sip:split.savings, ef:split.ef} : {family:sumAmt(due.filter(isFamilyItem)), sip:0, ef:0};
  const pick = k => typeof o[k] === "number" ? o[k] : def[k];
  const family = pick("family"), sip = pick("sip"), ef = pick("ef");
  const cards = cardBillsFor(cyc), cardsTotal = sumAmt(cards);
  return {cyc, rule, sal, amt, def:Object.assign({sal:sal.amt}, def), family, sip, ef, fixed, fixedTotal, cards, cardsTotal,
          spend:amt - family - sip - ef - fixedTotal - cardsTotal, split, edited:salSet || ["family","sip","ef"].some(k => typeof o[k] === "number")};
}

/** Payday to payday. On payday itself a new cycle starts. */
function payCycle(){
  const now = sod(new Date());
  let p1 = payOn(now.getFullYear(), now.getMonth());
  if(p1 <= now) p1 = payOn(now.getFullYear(), now.getMonth() + 1);
  const p0 = payOn(p1.getFullYear(), p1.getMonth() - 1);
  return {p0, p1, daysLeft:Math.max(1, days(now, p1)), cycleDays:Math.max(1, days(p0, p1)), dayOf:days(p0, now)};
}

function cycleSpend(cyc){
  const start = cyc.p0.getTime();
  let total = 0;
  const skipCards = cardsPaidLater(cyc);
  TX.forEach(t => {
    const x = withRules(t);
    if(x.ts < start) return;
    if(skipCards && CARD_CFG[x.account]) return;            // paid from the salary its bill is due in
    if(x.dir === "out" && x.counted) total += x.amt;
    else if(x.dir === "in" && (CARD_CFG[x.account] || x.paidBack)) total -= x.amt;    // refund back to a card, or a friend paying you back
  });
  manual.forEach(m => { const [y,mo] = String(m.ym).split("-");
    if(new Date(+y, +mo - 1, m.d) < cyc.p0) return;
    if(m.dir === "in"){ if(m.c === "Paid back") total -= m.amt; return; }    // a friend paying you back
    if(manualCounted(m) && !(skipCards && GROUPS[m.acct])) total += m.amt; });
  return total;
}

/** Each goal needs (target − saved before this cycle) ÷ months left, funded in priority order.
    Under the salary rule, goals come out of the savings share, and the emergency fund gets the
    rule's 10% instead of being planned like a goal. */
function goalPlan(cyc){
  const mp = monthPlan(cyc), rule = mp.rule, split = mp.split, ef = rule ? efGoal() : null;
  let avail = rule ? mp.sip : Math.max(0, mp.spend - (settings.buffer || 0));
  return goals.map(g => {
    if(ef && g.id === ef.id){
      const saved = goalSavedBefore(g, new Date(8.64e15)), before = goalSavedBefore(g, cyc.p0);
      const target = split.cap;
      return {g:Object.assign({}, g, {target}), saved, movedNow:saved - before, need:mp.ef, monthsLeft:Math.max(1, Math.ceil((target - saved) / (split.efRule || 1))),
              done:saved >= target - 0.5, due:new Date(g.date + "T00:00:00"), pct:Math.min(100, target ? saved / target * 100 : 0), byRule:true};
    }
    const emis = emisFor(g);
    if(emis.length){                       // paid for by instalments instead of saving up
      const today = sod(new Date()), paid = sumAmt(emis.filter(p => parseISO(p.due) <= today));
      const next = emis.find(p => parseISO(p.due) > today) || null, total = sumAmt(emis);
      return {g:Object.assign({}, g, {target:total}), saved:paid, movedNow:0, need:0, monthsLeft:1, done:!next,
              due:parseISO(emis[emis.length - 1].due), pct:Math.min(100, total ? paid / total * 100 : 0), byEmi:{emis, next}};
    }
    const mine = contribs.filter(c => c.goal === g.id);
    const saved = (g.start || 0) + mine.reduce((s,c) => s + c.amt, 0);
    const before = (g.start || 0) + mine.filter(c => new Date(c.date + "T12:00:00") < cyc.p0).reduce((s,c) => s + c.amt, 0);
    const due = new Date(g.date + "T00:00:00");
    const monthsLeft = Math.max(1, (due.getFullYear() - cyc.p0.getFullYear()) * 12 + due.getMonth() - cyc.p0.getMonth());
    const done = saved >= g.target - 0.5;
    const need = done ? 0 : Math.max(0, Math.ceil((g.target - before) / monthsLeft));
    return {g, saved, movedNow:saved - before, need, monthsLeft, done, due,
            pct:Math.min(100, g.target ? saved / g.target * 100 : 0)};
  }).sort((a,b) => (a.g.prio || 2) - (b.g.prio || 2) || a.due - b.due)
    .map(p => {
      if(p.byRule || p.byEmi) return Object.assign(p, {funded:p.need, short:0});
      const funded = Math.min(p.need, avail); avail -= funded; return Object.assign(p, {funded, short:p.need - funded});
    });
}

/* ---------------- render: hero (daily allowance) ---------------- */
/* ---------------- render: hero (safe to spend) ----------------
   A forecast, not a budget guess. From today until the day before the payday after next, it lays out every rupee
   that will leave or reach your bank accounts:
     - each card's billed and unbilled amount on its due date (card spending is money already spent, so it is
       never assumed to be "paid by next month's salary"), and card EMIs scheduled onto a statement;
     - fixed payments such as an EMI, on their dates, until they're paid;
     - each salary the planner expects (or the real credit), and what it sends to family, SIP and the
       emergency fund; goal money still to move this month; your buffer.
   The daily figure is the smallest of:
     - at every date money goes out: (balance then − buffer) ÷ days until then;
     - at the end of the window: what's left ÷ days until then;
     - once a salary has started this month: your spending share left ÷ days to payday, so next month's share
       isn't spent early.
   If the balance would dip below the buffer anywhere, the figure is ₹0 and it says how short, when, and what
   would close the gap. */
const BIG_BILL = 10000;     // \u201cnext big payment\u201d
function forecast(cards){
  const b = bankBalance(); if(!b) return null;
  const today = sod(new Date()), cur = payCycle(), pc = planCycle(), buffer = settings.buffer || 0;
  const P1 = cur.p1, P2 = nextCycle(cur).p1;
  const ev = [], at = d => (d < today ? today : sod(d));
  const add = (d, amt, kind, what, extra) => { if(Math.abs(amt) >= 1) ev.push(Object.assign({d:at(d), amt, kind, what}, extra || {})); };
  const short = c => c.cfg.short.replace(/\s+add-on|\s*·\d{4}/g, "");

  // cards: what's billed on its due date, what's unbilled on the next one
  cards.forEach(c => {
    const nm = short(c);
    if(c.prevUnpaid >= 0.5) add(c.c.prevDue, -c.prevUnpaid, "card", nm + " earlier bill", {card:c});
    if(c.billedLeft - c.prevUnpaid >= 0.5) add(c.c.due, -(c.billedLeft - c.prevUnpaid), "card", nm + " bill", {card:c, min:c.minDue});
    if(c.unbilledLeft >= 0.5) add(c.c.nextDue, -c.unbilledLeft, "card", nm + ", spent since " + fmt(c.c.stmt), {card:c});
  });
  let H = addDays(P2, -1);
  ev.forEach(e => { if(e.d > H) H = e.d; });              // already-spent card money is always counted, even if due later

  // card EMIs the bank will put on a coming statement
  SCHEDULED.forEach(t => {
    const g = CARD_CFG[t.account] && CARD_CFG[t.account].group; if(!g || !isOpen(g)) return;
    const cfgG = GROUPS[g], c = cycleFor(cfgG, sod(new Date(t.ts))), due = addDays(c.nextStmt, cfgG.dueAfter);
    if(due <= H) add(due, -t.amt, "cardemi", (t.desc || "Card EMI").replace(/\s*-\s*scheduled$/i, "").replace(/\s*\(.*\)$/, ""), {charged:sod(new Date(t.ts))});
  });

  // fixed payments from the bank (not yet paid)
  const paidNames = new Set(PLANNED_TX.values());
  PLANNED.filter(p => !isFamilyItem(p)).forEach(p => {
    const d = parseISO(p.due);
    if(d <= H && d >= addDays(today, -7) && !paidNames.has(p.name)) add(d, -p.amt, "fixed", p.name);
  });

  // this month's salary, if a salary started it: what's still to come in or go out
  let mpCur = null;
  if(!pc.upcoming){
    mpCur = monthPlan(cur);
    if(!mpCur.sal.credited && days(cur.p0, today) <= 10){
      add(today, mpCur.amt, "salary", "Salary, " + payNote(mpCur.sal), {exp:true});
      add(today, -mpCur.family, "family", familyTitle()); add(today, -mpCur.sip, "sip", "SIP", {pause:true}); add(today, -mpCur.ef, "ef", "Emergency fund", {pause:true});
    } else if(mpCur.sal.credited){
      stillToSetAside(mpCur).forEach(r => {
        if(r.kind) add(today, -r.left, r.kind, r.kind === "family" ? familyTitle() : r.kind === "sip" ? "SIP" : "Emergency fund", {pause:r.kind !== "family"});
      });
    }
    if(!mpCur.rule) goalPlan(cur).forEach(p => { if(!p.byEmi && !p.byRule && p.funded - p.movedNow >= 1) add(today, -(p.funded - p.movedNow), "goal", "To " + p.g.name, {pause:true}); });
  }
  // every payday in the window: the salary and its transfers
  for(let cyc = nextCycle(cur), i = 0; cyc.p0 <= H && i < 6; cyc = nextCycle(cyc), i++){
    const mp = monthPlan(cyc), when = fmt(cyc.p0);
    add(cyc.p0, mp.amt, "salary", "Salary " + when + ", " + (mp.sal.credited ? "credited" : mp.edited && !mp.sal.credited ? "as planned" : payNote(mp.sal).replace(/^credited.*/, "credited")), {exp:!mp.sal.credited});
    add(cyc.p0, -mp.family, "family", familyTitle()); add(cyc.p0, -mp.sip, "sip", "SIP", {pause:true}); add(cyc.p0, -mp.ef, "ef", "Emergency fund", {pause:true});
  }

  // walk the days. Between two dates nothing changes except your own spending, so each stretch's balance has to
  // cover every day from today until the next date anything moves (or the end of the window).
  ev.sort((x, y) => x.d - y.d || (y.amt > 0) - (x.amt > 0) || x.amt - y.amt);
  const dates = [...new Set(ev.map(e => +e.d))].sort((x, y) => x - y);
  let bal = b.bal; const segs = [];
  if(!dates.length || dates[0] > +today) segs.push({d:today, bal, evs:[]});
  dates.forEach(t => {
    const evs = ev.filter(e => +e.d === t); evs.forEach(e => { bal += e.amt; });
    segs.push({d:new Date(t), bal, evs, why:evs.filter(e => e.amt < 0).sort((x, y) => x.amt - y.amt)[0] || null});
  });
  segs.forEach((g, i) => {
    g.until = i + 1 < segs.length ? segs[i + 1].d : addDays(H, 1);
    g.n = Math.max(1, days(today, g.until));
    g.pay = i + 1 < segs.length ? segs[i + 1].evs.find(e => e.kind === "salary") || null : null;
  });
  const room = g => g.bal - buffer;
  const end = segs[segs.length - 1];
  const low = segs.reduce((m, g) => (g.bal < m.bal ? g : m), segs[0]);
  const firstShort = segs.find(g => room(g) < 0) || null;
  let tight = segs.reduce((m, g) => (room(g) / g.n < room(m) / m.n ? g : m), segs[0]);
  let pace = Math.max(0, room(tight) / tight.n);

  // the month's spending share, once a salary has started it
  let env = null;
  if(mpCur){
    const plan = goalPlan(cur), goalsTotal = mpCur.rule ? 0 : plan.reduce((s,p) => s + Math.max(p.funded, p.movedNow), 0);
    const left = mpCur.spend - goalsTotal - buffer - cycleSpend(cur);
    env = {left, pace:Math.max(0, left / cur.daysLeft)};
    if(env.pace < pace){ pace = env.pace; tight = null; }
  }
  const bills = ev.filter(e => e.amt < 0 && /card|cardemi|fixed/.test(e.kind));
  const nextPay = bills[0] || null, nextBig = bills.find(e => e.amt <= -BIG_BILL) || null;
  return {b, today, cur, P1, P2, H, ev, segs, end, low, firstShort, tight, pace, env, buffer, nextPay, nextBig, shortBy:firstShort ? -room(low) : 0};
}

/** What a month's split still has to take out of your account: each planner amount (and fixed
    payment) less what has already gone out for it in that pay cycle. SIP counts any investment debit;
    the emergency fund also counts money logged to an "Emergency fund" goal. */
function stillToSetAside(mp){
  const lo = mp.cyc.p0.getTime() - 5 * DAY, hi = mp.cyc.p1.getTime();
  const inCyc = t => t.ts >= lo && t.ts < hi;
  const sent = name => TX.filter(t => inCyc(t) && PLANNED_TX.get(t.id) === name).reduce((a,t) => a + t.amt, 0);
  const invested = TX.filter(t => isBank(t) && t.dir === "out" && !SELF_TX.has(t.id) && inCyc(t) && !PLANNED_TX.has(t.id) && withRules(t).cat === "Investments")
    .reduce((a,t) => a + t.amt, 0);
  const g = efGoal(), efLogged = g ? contribs.filter(c => c.goal === g.id && inCyc({ts:new Date(c.date + "T12:00:00").getTime()}))
    .reduce((a,c) => a + c.amt, 0) : 0;
  return [
    {name:FAMILY || "family", kind:"family", left:mp.family - sent(familyItem())},
    {name:"SIP", kind:"sip", left:mp.sip - sent("SIP") - invested},
    {name:"emergency fund", kind:"ef", left:mp.ef - sent("Emergency fund") - efLogged}]
    .concat(mp.fixed.map(p => ({name:p.name.replace(/\s+\d+ of \d+$/, ""), left:p.amt - sent(p.name)})))
    .map(r => Object.assign(r, {left:Math.max(0, r.left)})).filter(r => r.left >= 1);
}

/* ---------------- each transaction as the app shows it ----------------
   Card payments and transfers the planner already set aside are worked out by the engine. After that, your own
   edits win: a note's category beats a payee rule, and a payee rule beats the category the alert came with.
   "Spent for someone else" keeps the category but stops it counting as your spending. */
function ruleFor(desc){ const k = ruleKey(desc); return k && catRules[k] ? {pattern:k, category:catRules[k]} : null; }
function withRules(x){
  const n = noteOf(x.id), note = n && n.note ? {note:n.note} : null;
  if(PAY_INFO.candidates.has(x.id)){
    const dt = PAY_INFO.detail[x.id] || {};
    return Object.assign({}, x, {cat:"Card payment", counted:false, payCard:PAY_INFO.byTx[x.id] || null,
                                 payConfirmed:!!dt.confirmed, paySaved:dt.saved || 0, payOther:dt.other || null}, note);
  }
  if(x.dir === "in" && paidBack(x.id)) return Object.assign({}, x, {cat:"Paid back", counted:false, paidBack:true}, note);
  if(n && n.category) return Object.assign({}, x, {cat:n.category, counted:x.dir === "out" && !n.for_someone_else && !NOT_SPENDING.has(n.category), noted:true, forOther:x.dir === "out" && !!n.for_someone_else}, note);
  if(n && n.for_someone_else && x.dir === "out"){
    const base = CONTRIB_TX.has(x.id) || PLANNED_TX.has(x.id) ? x : withRuleOnly(x);
    return Object.assign({}, base, {counted:false, forOther:true, noted:true}, note);
  }
  if(SELF_TX.has(x.id)) return Object.assign({}, x, {cat:"Cash & transfers", counted:false, own:true}, note);
  if(CONTRIB_TX.has(x.id)) return Object.assign({}, x, {cat:"Moved to goals", counted:false}, note);
  if(PLANNED_TX.has(x.id)) return Object.assign({}, x, {cat:"Planned payment", counted:false, planned:PLANNED_TX.get(x.id)}, note);
  return note ? Object.assign({}, withRuleOnly(x), note) : withRuleOnly(x);
}
function withRuleOnly(x){
  const r = catRules[ruleKey(x.desc)];
  if(!r || r === x.cat) return x;
  return Object.assign({}, x, {cat:r, counted: x.dir === "out" && !NOT_SPENDING.has(r), ruled:true});
}

/* =============================================================================================
   Models: everything a screen shows, worked out here and handed to the screens as plain data.
   ============================================================================================= */
const DOW = ["Sun","Mon","Tue","Wed","Thu","Fri","Sat"];
const fmtD = d => DOW[d.getDay()] + " " + fmt(d);                       // "Mon 30 Nov"
const ymOf = d => d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0");
const ymAdd = (ym, n) => { const [y, m] = ym.split("-").map(Number); return ymOf(new Date(y, m - 1 + n, 1)); };
const ymName = (ym, short) => { const [y, m] = ym.split("-").map(Number); return (short ? MON : MONFULL)[m - 1] + (short ? "" : " " + y); };
/** Bank text tidied for a title: "Phone EMI 3 of 3 (3,196.80 + 47.90 interest + 8.62 GST) - scheduled" → "Phone EMI 3 of 3". */
const tidy = s => String(s || "").replace(/\s*-\s*(scheduled)?\s*$/i, "").replace(/\s*\([^()]*\)\s*$/, "").replace(/\s+/g, " ").trim();
/** A card account's short name: "Bank Gold add-on ·1234" → "Bank Gold". */
const cardShort = g => GROUPS[g] ? GROUPS[g].short.replace(/\s+add-on|\s*·\d{4}/g, "") : g;
const sumOf = (list, f) => list.reduce((s, x) => s + (f ? f(x) : x), 0);

/* ---------------- Today: the daily figure ---------------- */
/** One forecast event as a row: a short title and one line of detail. */
function evRow(e){
  const when = fmt(e.d);
  if(e.kind === "card"){
    const nm = e.card ? cardShort(e.card.key) : e.what.replace(/(,| earlier| bill).*$/, "");
    if(/, spent since /.test(e.what)) return {title:nm + " bill", detail:"spent since " + e.what.replace(/^.*, spent since /, "") + " · due " + when};
    if(/ earlier bill$/.test(e.what)) return {title:nm + " earlier bill", detail:"unpaid · due " + when};
    return {title:nm + " bill", detail:"due " + when};
  }
  if(e.kind === "cardemi") return {title:tidy(e.what), detail:"on the card, due " + when};
  if(e.kind === "fixed") return {title:e.what.replace(/\s+(\d+) of (\d+)$/, " $1/$2"), detail:when};
  if(e.kind === "salary"){
    const m = e.what.match(/^Salary(?: (\d+ \w{3}))?, (.*)$/);
    return {title:"Salary", detail:(m && m[1] ? m[1] + ", " : when + ", ") + (m ? m[2] : "expected")};
  }
  if(e.kind === "family") return {title:familyTitle(), detail:when};
  if(e.kind === "sip") return {title:"SIP", detail:when};
  if(e.kind === "ef") return {title:"Emergency fund", detail:when};
  if(e.kind === "goal") return {title:e.what, detail:when};
  return {title:e.what, detail:when};
}
/** The card behind a forecast event, and how late it is. */
function evOverdue(e){
  if(!e.card) return 0;
  const c = e.card, due = / earlier bill$/.test(e.what) ? c.c.prevDue : /, spent since /.test(e.what) ? c.c.nextDue : c.c.due;
  const n = days(sod(new Date()), due);
  return n < 0 ? -n : 0;
}

function heroModel(cards){
  if(!settings.inc) return {state:"noinc"};
  const f = forecast(cards);
  if(!f) return {state:"nobal"};
  const keeps = f.buffer ? "Keeps " + money(f.buffer) + " in the bank" : "Keeps your bank above ₹0";
  let line, tone = "", explain;
  if(f.firstShort){
    const w = f.low.why, nm = w ? evRow(w).title : "";
    line = money(f.shortBy) + " short on " + fmtD(f.low.d);
    tone = "alert";
    explain = "Your balance would be " + money(f.shortBy) + " short on " + fmt(f.low.d) + (w ? ", when the " + nm + (w.kind === "card" || w.kind === "fixed" ? " is due" : " goes out") : "") + "." +
      (f.firstShort.d - f.low.d ? " It first drops below " + (f.buffer ? "your buffer" : "zero") + " on " + fmt(f.firstShort.d) + "." : "");
  } else if(!f.tight){
    line = "Your spending share until payday, " + fmtD(f.cur.p1);
    explain = "What's left of this month's spending share, " + money(f.env.left) + ", spread over the " + f.cur.daysLeft + (f.cur.daysLeft === 1 ? " day" : " days") + " until payday on " + fmt(f.cur.p1) + ".";
  } else {
    const g = f.tight, til = g.pay ? fmtD(g.until) : fmtD(addDays(g.until, -1));
    line = keeps + " until " + (g.pay ? "payday, " : "") + til;
    const after = g.why ? "After the " + money(-g.why.amt) + " " + evRow(g.why).title + " on " + fmt(g.d) + ", " : "";
    explain = (after ? after + money(g.bal - f.buffer) : money(g.bal - f.buffer)) + " has to last until " + (g.pay ? "your salary on " + fmt(g.until) : fmt(addDays(g.until, -1))) + ".";
  }

  // how it's worked out: one row per payment, grouped where there are many of one kind
  const rows = f.b.parts.filter(p => p.set).map(p => ({title:"In your " + p.name + " account", detail:"tracked from alerts", amt:p.bal}));
  f.ev.filter(e => e.kind === "salary").forEach(e => rows.push(Object.assign(evRow(e), {amt:e.amt, tone:"pos"})));
  f.ev.filter(e => /^(card|cardemi|fixed)$/.test(e.kind)).forEach(e => rows.push(Object.assign(evRow(e), {amt:e.amt})));
  [["family", familyTitle()], ["sip", "SIP"], ["ef", "Emergency fund"], ["goal", "Goal money to move"]].forEach(([k, title]) => {
    const list = f.ev.filter(e => e.kind === k); if(!list.length) return;
    const v = sumOf(list, e => e.amt); if(!v) return;
    rows.push({title, detail:andList(list.map(e => fmt(e.d))), amt:v});
  });
  if(f.buffer) rows.push({title:"Buffer you keep", detail:"never spent", amt:-f.buffer});
  const endLeft = f.end.bal - f.buffer;
  rows.push({title:"Left on " + fmt(f.H), detail:"the day before the salary after next", amt:endLeft, total:true});
  if(f.low !== f.end && f.low.bal < f.end.bal - 0.5) rows.push({title:"Lowest point", detail:fmtD(f.low.d), amt:f.low.bal - f.buffer, total:true, tone:f.firstShort ? "alert" : ""});

  // ways to close a gap
  const fixes = [];
  let leftToFind = 0;
  if(f.firstShort){
    const before = f.ev.filter(e => e.d <= f.low.d);
    before.filter(e => e.kind === "sip").forEach(e => fixes.push({title:"Skip the SIP", detail:fmt(e.d), amt:-e.amt}));
    before.filter(e => e.kind === "ef").forEach(e => fixes.push({title:"Skip the emergency-fund transfer", detail:fmt(e.d), amt:-e.amt}));
    before.filter(e => e.kind === "goal").forEach(e => fixes.push({title:"Hold off moving goal money", detail:e.what.replace(/^To /, "") + " · " + fmt(e.d), amt:-e.amt}));
    before.filter(e => e.kind === "card" && e.min && -e.amt - e.min >= 1).forEach(e => fixes.push({title:"Pay only the minimum", detail:evRow(e).title + " · interest applies", amt:-e.amt - e.min}));
    before.filter(e => e.kind === "family").forEach(e => fixes.push({title:"Send less to " + (FAMILY || "family"), detail:fmt(e.d), amt:-e.amt, upTo:true}));
    leftToFind = Math.max(0, f.shortBy - sumOf(fixes, x => x.amt));
  }

  // the next payment, and the next big one
  const pay = e => e ? Object.assign(evRow(e), {amt:-e.amt, d:e.d, overdue:evOverdue(e)}) : null;
  const nextPay = pay(f.nextPay), nextBig = f.nextBig && f.nextBig !== f.nextPay ? pay(f.nextBig) : null;

  return {state:"ok", f, pace:f.pace, line, tone, explain, rows, fixes, leftToFind, nextPay, nextBig, tiles:heroTiles(f), chart:balanceChart(f)};
}

/** Three tiles under the chart: the rest of this month, next month and a usual month, each as a total and per day. */
function heroTiles(f){
  const daysLeft = Math.max(1, days(f.today, f.P1));
  const rest = {total:f.pace * daysLeft, perDay:f.pace, days:daysLeft};
  // next month, if this month spends at today's figure: each stretch after payday has to last from payday
  const spentBefore = f.pace * days(f.today, f.P1), cycDays = Math.max(1, days(f.P1, f.P2));
  const after = f.segs.filter(g => g.d >= f.P1);
  let nextPace = after.length ? Math.min.apply(null, after.map(g => (g.bal - spentBefore - f.buffer) / Math.max(1, days(f.P1, g.until)))) : 0;
  const nmp = monthPlan(nextCycle(f.cur));
  nextPace = Math.max(0, Math.min(nextPace, (nmp.spend - f.buffer) / cycDays));
  const next = {total:nextPace * cycDays, perDay:nextPace, days:cycDays, from:f.P1};
  const u = usualMonth();
  return {rest, next, usual:u ? {total:u.spend, perDay:u.spend / 30, days:30} : null};
}

/** The bank balance day by day until the salary after next: a step for each date money moves. */
function balanceChart(f){
  const pts = [], end = addDays(f.H, 1);
  f.segs.forEach((g, i) => { pts.push({d:g.d, bal:g.bal}); });
  return {pts, from:f.today, to:end, buffer:f.buffer, low:{d:f.low.d, bal:f.low.bal}, paydays:[f.P1, f.P2].filter(d => d <= end)};
}

/** A month with no one-off payments: your salary split by your rule. */
function usualMonth(){
  const inc = settings.inc || 0; if(!inc) return null;
  const g = efGoal(), s = splitSalary(inc, g ? goalSavedBefore(g, new Date(8.64e15)) : 0);
  return {amt:inc, family:s.family, sip:s.savings, ef:s.ef, spend:s.spend, efFull:s.efFull, rule:!!SALARY_RULE,
          pct:{family:SALARY_RULE.family, sip:s.savings / inc, ef:s.ef / inc, spend:s.spend / inc}};
}

/* ---------------- Today: where you stand ---------------- */
function netModel(cards){
  const b = bankBalance(), cyc = payCycle(), inc = settings.inc || 0, pc = planCycle();
  const billed = cards.reduce((s,c) => s + c.billedLeft, 0);
  const unbilled = cards.reduce((s,c) => s + c.unbilledLeft, 0);
  if(!b) return null;
  const cur = monthPlan(cyc), curIn = !!inc && !pc.upcoming && !!cur.sal.credited;   // this month's salary is in the balance
  const owe = curIn ? stillToSetAside(cur) : [], oweTotal = owe.reduce((a,r) => a + r.left, 0);
  const nxt = !inc ? null : curIn ? monthPlan(nextCycle(cyc)) : monthPlan(pc);
  const setAt = k => { const b = bankByKey(k) || BANKS[0]; return b ? settings[b.at] || 0 : 0; };
  const nxtIn = !!(curIn && nxt.sal.credited && nxt.sal.credited.getTime() > setAt(nxt.sal.bank));   // landed before payday
  const oweNext = nxtIn ? stillToSetAside(nxt) : [], oweNextTotal = oweNext.reduce((a,r) => a + r.left, 0);
  const now = b.bal - oweTotal - oweNextTotal - billed - unbilled;
  let next = null;
  if(nxt && !nxtIn){
    const s = nxt.sal, e = s.exp || {};
    const status = s.credited ? "credited" : e.partial && e.assumed ? "not confirmed" : e.partial ? "estimate" : "expected";
    next = {mp:nxt, status, basis:curIn ? "at your rule" : "from the planner", then:now + nxt.spend + nxt.cardsTotal};   // `now` already takes off every card
  }
  const age = b.since ? Math.floor((Date.now() - b.since) / DAY) : null;
  return {b, billed, unbilled, owe, oweTotal, oweNext, oweNextTotal, nxtCredited:nxtIn ? nxt.sal.credited : null, now, next, age};
}

/* ---------------- Coming up, and the calendar ---------------- */
/** Card dates, as the old timeline listed them (bill due, statement closes, next bill due, scheduled charges). */
function cardTimeline(cards){
  const ev = [];
  cards.forEach(c => {
    if(c.prevUnpaid >= 0.5) ev.push({d:c.c.prevDue, stmt:false, what:c.cfg.short + " earlier bill, unpaid", amt:c.prevUnpaid, card:c.key, kind:"earlier"});
    if(c.billedLeft - c.prevUnpaid >= 0.5) ev.push({d:c.c.due, stmt:false, what:c.cfg.short + " bill due", amt:c.billedLeft - c.prevUnpaid, card:c.key, kind:"bill"});
    ev.push({d:c.c.nextStmt, stmt:true, what:c.cfg.short + " statement closes", amt:c.unbilledLeft, card:c.key, kind:"stmt"});
    ev.push({d:c.c.nextDue, stmt:false, what:c.cfg.short + " next bill due", amt:c.unbilledLeft, card:c.key, kind:"next"});
  });
  SCHEDULED.forEach(t => ev.push({d:sod(new Date(t.ts)), stmt:true, what:(t.desc || "Scheduled charge").replace(/\s*-\s*scheduled$/i, "") + " · billed to " + acctName(t.account), amt:t.amt,
    card:CARD_CFG[t.account] ? CARD_CFG[t.account].group : null, kind:"charge", desc:t.desc}));
  ev.sort((a,b) => a.d - b.d);
  return ev;
}
/** Everything with a date: card bills and statements, card EMIs, salaries, transfers and fixed payments.
    dot: "in" money in, "bill" a card bill or card charge, "out" money you send, "stmt" a statement closing. */
function calendarEvents(cards, f){
  const today = sod(new Date()), out = [];
  cardTimeline(cards).forEach(e => {
    const nm = cardShort(e.card);
    if(e.kind === "earlier") out.push({d:e.d, dot:"bill", title:nm + " earlier bill", detail:"unpaid", amt:-e.amt, card:e.card});
    else if(e.kind === "bill") out.push({d:e.d, dot:"bill", title:nm + " bill due", detail:"billed " + fmt(cards.find(c => c.key === e.card).c.stmt), amt:-e.amt, card:e.card});
    else if(e.kind === "stmt") out.push({d:e.d, dot:"stmt", title:nm + " statement", detail:e.amt >= 0.5 ? "closes · spent so far" : "closes", amt:e.amt >= 0.5 ? e.amt : null, card:e.card, soft:true});
    else if(e.kind === "next") { if(e.amt >= 0.5) out.push({d:e.d, dot:"bill", title:nm + " next bill", detail:"due, so far", amt:-e.amt, card:e.card}); }
    else if(e.kind === "charge") out.push({d:e.d, dot:"bill", title:tidy(e.desc || e.what), detail:"charged to " + nm, amt:e.amt, card:e.card, soft:true});
  });
  if(f) f.ev.forEach(e => {
    if(e.kind === "card" || e.kind === "cardemi") return;          // the card dates above already cover these
    const r = evRow(e), dot = e.kind === "salary" ? "in" : "out";
    const still = +e.d === +today && e.kind !== "salary" && e.kind !== "fixed" && +today !== +f.cur.p0;
    out.push({d:e.d, dot, title:r.title, detail:e.kind === "salary" ? r.detail.replace(/^\d+ \w{3}, /, "") : e.kind === "fixed" ? "fixed payment" : still ? "still to set aside" : "from the salary", amt:e.amt});
  });
  out.forEach(e => { e.n = days(today, e.d); e.overdue = e.n < 0 && e.dot === "bill" && !e.soft; });
  out.sort((a, b) => a.d - b.d || (a.dot === "in") - (b.dot === "in") * 1);
  return out;
}
/** Coming up: from today on, grouped by day. */
function comingUp(cards, f){
  const byDay = [];
  calendarEvents(cards, f).filter(e => e.n >= 0).forEach(e => {
    const last = byDay[byDay.length - 1];
    if(last && +last.d === +e.d) last.items.push(e); else byDay.push({d:e.d, n:e.n, items:[e]});
  });
  return byDay;
}

/* ---------------- Needs attention ---------------- */
function attention(cards, hero, net){
  const out = [], f = hero && hero.f, today = sod(new Date());
  cards.forEach(c => {
    if(c.billedLeft >= 0.5 && c.dueIn < 0 && !c.preFirst)
      out.push({tone:"alert", icon:"card", title:cardShort(c.key) + " bill is overdue", detail:(-c.dueIn) + (c.dueIn === -1 ? " day" : " days") + " late · due " + fmt(c.prevUnpaid >= 0.5 ? c.c.prevDue : c.c.due), amt:c.billedLeft, go:{view:"cards", card:c.key}});
    else if(c.billedLeft >= 0.5 && c.dueIn >= 0 && c.dueIn <= 3)
      out.push({tone:"warn", icon:"card", title:cardShort(c.key) + " bill " + countdown(c.dueIn), detail:"due " + fmtD(c.dueIn === 0 ? today : addDays(today, c.dueIn)), amt:c.billedLeft, go:{view:"cards", card:c.key}});
  });
  if(f && f.firstShort) out.push({tone:"alert", icon:"gap", title:"Short by " + money(f.shortBy) + " on " + fmt(f.low.d), detail:hero.fixes.length ? hero.fixes.length + (hero.fixes.length === 1 ? " way" : " ways") + " to close the gap" : "spend less until then", amt:null, go:{sheet:"explain"}});
  const un = PAY_INFO.unresolved.filter(t => t.ts > Date.now() - 60 * DAY);
  if(un.length) out.push({tone:"warn", icon:"card", title:un.length === 1 ? "A card payment needs its card" : un.length + " card payments need their card", detail:"no confirmation email said which", amt:sumOf(un, t => t.amt), go:{view:"cards"}});
  if(settings.inc){
    const mp = monthPlan(planCycle());
    if(mp.spend < 0) out.push({tone:"warn", icon:"plan", title:"The split is more than the salary", detail:"pull a slider back on Plan", amt:-mp.spend, go:{view:"plan"}});
    if(f && f.env && !planCycle().upcoming){
      const cyc = f.cur, mpc = monthPlan(cyc), plan = goalPlan(cyc);
      const unmoved = mpc.rule ? [] : plan.filter(p => p.funded - p.movedNow >= 1);
      // only what hasn't gone out yet: money already sent to family, the SIP or a fixed payment drops off the list
      const moves = stillToSetAside(mpc).map(r => r.name).concat(unmoved.map(p => p.g.name));
      if(cyc.dayOf <= 3 && moves.length) out.push({tone:"info", icon:"plan", title:"Payday: set money aside first", detail:andList(moves), amt:null, go:{view:"plan"}});
      const goalsShort = sumOf(plan.filter(p => !p.byRule), p => p.short);
      if(goalsShort >= 1) out.push({tone:"warn", icon:"goal", title:"Goals need more than " + (mpc.rule ? "your SIP share" : "is free"), detail:"push a date back or trim a target", amt:goalsShort, go:{view:"plan"}});
    }
  }
  if(net && net.b.missing.length) out.push({tone:"info", icon:"bank", title:"Set your " + net.b.missing.join(" and ") + " balance", detail:"until then it counts as ₹0", amt:null, go:{sheet:"balance"}});
  else if(net && net.age !== null && net.age >= 30) out.push({tone:"info", icon:"bank", title:"Check your bank balances", detail:"last set " + net.age + " days ago", amt:null, go:{sheet:"balance"}});
  if(lastRun && Date.now() - lastRun > 6 * 3600000) out.push({tone:"warn", icon:"mail", title:"No new emails read for " + ago(lastRun).replace(/ ago$/, ""), detail:"the collector may have stopped", amt:null, go:{view:"settings"}});
  if(DATA_IN && !NOTES_OK && window.MONEY && MONEY.notesChecked) out.push({tone:"info", icon:"db", title:"One database update is needed", detail:"for notes and payee rules", amt:null, go:{view:"settings"}});
  return out;
}

/* ---------------- Plan: EMIs, with how many are done ---------------- */
function emiModel(){
  const today = sod(new Date()), now = Date.now(), out = [];
  const re = /^(.*?\bEMI)\s+(\d+)\s+of\s+(\d+)/i, groups = {};
  TX.concat(SCHEDULED).forEach(t => {
    if(t.dir !== "out" || !CARD_CFG[t.account] || !isOpen(CARD_CFG[t.account].group)) return;   // a closed card's EMIs are paid off
    const m = re.exec(t.desc || ""); if(!m) return;
    const key = m[1].toLowerCase() + "|" + CARD_CFG[t.account].group + "|" + m[3];
    (groups[key] = groups[key] || {name:m[1].trim(), where:cardShort(CARD_CFG[t.account].group), on:"card", n:+m[3], items:[]})
      .items.push({k:+m[2], amt:t.amt, d:sod(new Date(t.ts)), done:!(t.ts > now)});
  });
  const pre = /^(.*?)\s+(\d+) of (\d+)$/, paid = new Set(PLANNED_TX.values());
  PLANNED.forEach(p => {
    const m = pre.exec(p.name); if(!m) return;
    const key = m[1].toLowerCase() + "|bank|" + m[3];
    (groups[key] = groups[key] || {name:m[1].trim(), where:"Bank", on:"bank", n:+m[3], items:[]})
      .items.push({k:+m[2], amt:p.amt, d:parseISO(p.due), done:paid.has(p.name) || parseISO(p.due) <= today});
  });
  Object.values(groups).forEach(g => {
    g.items.sort((a, b) => a.k - b.k);
    const done = g.items.filter(i => i.done), next = g.items.find(i => !i.done) || null, per = g.items[g.items.length - 1].amt;
    const unknown = Math.max(0, g.n - g.items.length);
    out.push({name:g.name, where:g.where, on:g.on, tenure:g.n, done:done.length ? Math.max.apply(null, done.map(i => i.k)) : 0, per,
              next, left:sumOf(g.items.filter(i => !i.done), i => i.amt) + unknown * per, total:sumOf(g.items, i => i.amt) + unknown * per,
              last:g.items[g.items.length - 1].d});
  });
  return out.sort((a, b) => (a.done >= a.tenure) - (b.done >= b.tenure) || (a.next ? a.next.d : 0) - (b.next ? b.next.d : 0));
}

/* ---------------- Cards ---------------- */
function sourceNote(c){
  return c.source === "you" ? "entered by you" : c.source === "alerts" ? "added up from alerts — no statement email yet" :
         c.source === "CRED" ? "from CRED's bill email" : "from " + c.source + "'s statement";
}
/** The payments shown under a card: the last few since the statement before this one. */
function cardPayments(c){
  const since = c.c.prevStmt.getTime() - 5 * DAY;
  return EFF_PAYMENTS.filter(p => p.group === c.key && p.ts > since).sort((a,b) => b.ts - a.ts).slice(0, 6).map(p => {
    const before = p.ts <= c.from;
    const how = p.kind === "confirmed" ? p.srcs.join(" + ") + " confirmed" + (p.txId ? "" : ", not from your bank") : p.kind === "inferred" ? "matched from " + payBank(p) : "entered by you";
    const off = p.saved >= 0.5 ? (p.kind === "confirmed" ? "CRED took " : "assuming CRED took ") + money2(p.saved) + " off" : "";
    return Object.assign({}, p, {before, how, off, beforeText:before ? (c.source === "alerts" ? "paid the earlier bill" : "in this bill") : ""});
  });
}

const payBank = p => { const t = p.txId && TX.find(x => x.id === p.txId), b = t && bankOf(t); return b ? b.name : "your bank"; };

/* ---------------- Spending and Activity ---------------- */
function manualTx(m){
  const card = m.acct && GROUPS[m.acct] ? m.acct : null;
  const bank = bankByKey(m.acct);
  const x = {id:m.id, account:card ? GROUPS[card].short : m.acct === "cash" ? "Cash" : bank ? bank.full : "Added by you", kind:card ? "card" : "bank",
    ts:m.ts || 0, day:m.d, ym:m.ym, amt:m.amt, dir:m.dir === "in" ? "in" : "out", desc:m.t, cat:m.c, counted:m.dir !== "in", man:true, card};
  const n = noteOf(m.id);
  if(x.dir === "in"){                                   // money you received: never spending; "Paid back" takes some off
    if(n && n.category){ x.cat = n.category; x.noted = true; }
    if(n && n.note) x.note = n.note;
    if(x.cat === "Paid back") x.paidBack = true;
    return x;
  }
  if(n){
    if(n.category){ x.cat = n.category; x.counted = !NOT_SPENDING.has(n.category); x.noted = true; }
    if(n.for_someone_else){ x.counted = false; x.forOther = true; x.noted = true; }
    if(n.note) x.note = n.note;
  }
  if(x.counted && NOT_SPENDING.has(x.cat)) x.counted = false;
  return x;
}
const manualCounted = m => manualTx(m).counted;
/** Transactions as the app shows them: one month (ym "2026-12"), or all of them (ym null). */
function txFor(ym){
  const pick = x => !ym || x.ym === ym;
  return TX.filter(pick).map(withRules)
    .map(x => CARD_CFG[x.account] ? Object.assign({}, x, {account:acctName(x.account), card:CARD_CFG[x.account].group}) : x)
    .concat(manual.filter(pick).map(manualTx));
}
let MONTHS = [];
function buildMonths(){
  const set = new Set(TX.map(x => x.ym).concat(manual.map(m => m.ym)));
  set.add(ymOf(new Date()));
  MONTHS = Array.from(set).sort().reverse();
  if(!currentYM || !set.has(currentYM)) currentYM = MONTHS[0];
}
/** What counts as spending in a list of transactions: counted spends, less refunds to cards and money friends paid back. */
function spendOf(tx){
  const cardRefunds = sumOf(tx.filter(x => x.dir === "in" && x.kind === "card"), x => x.amt);
  const paybacks = sumOf(tx.filter(x => x.paidBack), x => x.amt);
  return {spend:sumOf(tx.filter(x => x.dir === "out" && x.counted), x => x.amt) - cardRefunds - paybacks, cardRefunds, paybacks};
}
/** Month by month: counted spending (manual entries included), less money friends paid back. */
function trendAll(){
  const bm = {}, all = TX.map(withRules);
  all.filter(x => x.dir === "out" && x.counted).forEach(x => bm[x.ym] = (bm[x.ym] || 0) + x.amt);
  manual.forEach(m => { if(manualCounted(m)) bm[m.ym] = (bm[m.ym] || 0) + m.amt; else if(m.dir === "in" && m.c === "Paid back") bm[m.ym] = (bm[m.ym] || 0) - m.amt; });
  all.filter(x => x.paidBack).forEach(x => bm[x.ym] = (bm[x.ym] || 0) - x.amt);
  return bm;
}
function spendModel(ym){
  const tx = txFor(ym);
  const {spend, cardRefunds, paybacks} = spendOf(tx);
  const cardOut = sumOf(tx.filter(x => x.kind === "card" && x.dir === "out"), x => x.amt);
  const skipped = sumOf(tx.filter(x => x.dir === "out" && !x.counted), x => x.amt);
  const counted = tx.filter(x => x.dir === "out" && x.counted);
  const [Y, M] = ym.split("-").map(Number), lastDay = new Date(Y, M, 0).getDate();
  const totals = {};
  counted.forEach(x => totals[x.cat] = (totals[x.cat] || 0) + x.amt);
  const cats = Object.entries(totals).sort((a, b) => b[1] - a[1]).map(([name, amt]) => ({name, amt, pct:spend > 0 ? amt / spend * 100 : 0}));
  const acc = {};
  tx.forEach(x => { acc[x.account] = acc[x.account] || {out:0, n:0}; acc[x.account].n++; if(x.dir === "out" && x.counted) acc[x.account].out += x.amt; });
  const accts = Object.keys(acc).sort((a, b) => acc[b].out - acc[a].out).map(k => ({name:k, out:acc[k].out, n:acc[k].n}));
  const byDay = new Array(lastDay).fill(0);
  counted.forEach(x => { if(x.day >= 1 && x.day <= lastDay) byDay[x.day - 1] += x.amt; });
  // compared with last month by the same day of the month
  const now = new Date(), isCur = ym === ymOf(now), upTo = isCur ? now.getDate() : lastDay;
  const prevYM = ymAdd(ym, -1), prevTx = txFor(prevYM);
  const toDay = (list, d) => spendOf(list.filter(x => x.day <= d)).spend;
  const lastBy = toDay(prevTx, upTo), thisBy = isCur ? toDay(tx, upTo) : spend;
  const vs = lastBy > 0 ? (thisBy - lastBy) / lastBy * 100 : null;
  const biggest = counted.slice().sort((a, b) => b.amt - a.amt)[0] || null;
  // where it went: payees, biggest first
  const pay = {};
  counted.forEach(x => { const k = ruleKey(x.desc) || x.desc; (pay[k] = pay[k] || {name:x.desc, amt:0, n:0, cat:x.cat}); pay[k].amt += x.amt; pay[k].n++; });
  const payees = Object.values(pay).sort((a, b) => b.amt - a.amt).slice(0, 6);
  // six months up to this one, with the average of the months before this one
  const bm = trendAll(), six = [];
  for(let i = 5; i >= 0; i--){ const k = ymAdd(ym, -i); six.push({ym:k, amt:bm[k] || 0, cur:k === ym}); }
  const done = six.filter(s => !(isCur && s.cur) && s.amt > 0);
  const avg = done.length ? sumOf(done, s => s.amt) / done.length : null;
  return {ym, tx, spend, cardOut, skipped, cardRefunds, paybacks, cats, accts, byDay, lastDay, upTo, isCur,
          perDay:spend / Math.max(1, upTo), lastBy, thisBy, vs, biggest, payees, six, avg, prevYM};
}

/** Every transaction, newest first, for Activity and the CSV export. */
function allTx(){
  return txFor(null).sort((a, b) => b.ym.localeCompare(a.ym) || b.day - a.day || (b.ts || 0) - (a.ts || 0));
}
const clockOf = x => x.ts ? new Date(x.ts).toLocaleTimeString("en-IN", {hour:"numeric", minute:"2-digit", hour12:true}).replace(/\s?([ap])\.?m\.?$/i, (m, ap) => " " + ap.toLowerCase() + "m") : "";
function csvText(){
  const q = v => { const s = String(v === null || v === undefined ? "" : v); return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s; };
  const rows = [["Date", "Time", "Account", "Payee", "Category", "Amount (₹)", "In or out", "Counted as spending", "Note"]];
  allTx().forEach(x => {
    const [y, m] = x.ym.split("-");
    rows.push([y + "-" + m + "-" + String(x.day).padStart(2, "0"), clockOf(x), x.account, x.desc, x.cat, (x.dir === "in" ? "" : "-") + x.amt.toFixed(2),
               x.dir === "in" ? "in" : "out", x.counted ? "yes" : "no", x.note || (x.forOther ? "spent for someone else" : "")]);
  });
  return rows.map(r => r.map(q).join(",")).join("\r\n");
}

/* ---------------- the snapshot: every figure, for the checks ---------------- */
function snapshot(){
  const r2 = v => typeof v === "number" ? Math.round(v * 100) / 100 : v;
  const d = x => x ? iso(x) : null;
  resolvePayments();
  const cards = allCards(), f = forecast(cards), out = {};
  out.forecast = f && {pace:r2(f.pace), shortBy:r2(f.shortBy), low:d(f.low.d), lowBal:r2(f.low.bal), end:r2(f.end.bal), H:d(f.H),
    first:f.firstShort ? d(f.firstShort.d) : null, env:f.env ? r2(f.env.left) : null, tight:f.tight ? d(f.tight.d) : null,
    ev:f.ev.map(e => [d(e.d), r2(e.amt), e.kind, e.what]), segs:f.segs.map(s => [d(s.d), r2(s.bal), s.n]),
    nextPay:f.nextPay ? [d(f.nextPay.d), r2(f.nextPay.amt), f.nextPay.what] : null,
    nextBig:f.nextBig ? [d(f.nextBig.d), r2(f.nextBig.amt), f.nextBig.what] : null};
  const mp = monthPlan(planCycle());
  out.plan = {p0:d(mp.cyc.p0), amt:r2(mp.amt), family:r2(mp.family), sip:r2(mp.sip), ef:r2(mp.ef), spend:r2(mp.spend),
    fixed:r2(mp.fixedTotal), rule:mp.rule, edited:mp.edited, credited:d(mp.sal.credited), upcoming:!!planCycle().upcoming};
  out.goals = goalPlan(payCycle()).map(p => ({id:p.g.id, saved:r2(p.saved), need:r2(p.need), funded:r2(p.funded), short:r2(p.short),
    moved:r2(p.movedNow), target:r2(p.g.target), done:p.done, months:p.monthsLeft}));
  out.cards = cards.map(c => ({k:c.key, billed:r2(c.billed), billedLeft:r2(c.billedLeft), unbilled:r2(c.unbilled), unbilledLeft:r2(c.unbilledLeft),
    paid:r2(c.paid), toBilled:r2(c.toBilled), prevUnpaid:r2(c.prevUnpaid), owed:r2(c.owed), state:c.state, dueIn:c.dueIn,
    due:d(c.c.due), stmt:d(c.c.stmt), nextDue:d(c.c.nextDue), prevDue:d(c.c.prevDue), source:c.source, min:c.minDue, refunds:r2(c.refunds), credit:r2(c.credit)}));
  out.payments = EFF_PAYMENTS.map(p => [p.group, p.ts, r2(p.amt), p.kind, p.txId || null].join("|")).sort();
  out.unresolved = PAY_INFO.unresolved.map(t => t.id);
  const n = netModel(cards);
  out.net = n && {bal:r2(n.b.bal), inn:r2(n.b.inn), out:r2(n.b.out), owe:n.owe.map(r => [r.name, r2(r.left)]), oweNext:n.oweNext.map(r => [r.name, r2(r.left)]),
    billed:r2(n.billed), unbilled:r2(n.unbilled), now:r2(n.now),
    next:n.next ? {p0:d(n.next.mp.cyc.p0), amt:r2(n.next.mp.amt), family:r2(n.next.mp.family), sip:r2(n.next.mp.sip), ef:r2(n.next.mp.ef),
                   fixed:n.next.mp.fixed.map(p => [p.name, r2(p.amt)]), then:r2(n.next.then)} : null};
  out.timeline = cardTimeline(cards).map(e => [d(e.d), e.stmt, e.what, r2(e.amt)]);
  out.months = {};
  Array.from(new Set(TX.map(x => x.ym).concat(manual.map(m => m.ym)))).sort().forEach(ym => {
    const s = spendModel(ym), byDay = {};
    s.byDay.forEach((v, i) => { if(v) byDay[i + 1] = r2(v); });
    out.months[ym] = {spend:r2(s.spend), cardOut:r2(s.cardOut), skipped:r2(s.skipped), cardRefunds:r2(s.cardRefunds), paybacks:r2(s.paybacks),
      cats:s.cats.map(c => [c.name, r2(c.amt)]).sort(), accts:s.accts.map(a => [a.name, r2(a.out), a.n]).sort(), byDay,
      tx:s.tx.map(x => [x.id, x.account, x.cat, x.counted, r2(x.amt), x.dir, x.day, !!x.paidBack, x.planned || null]).sort()};
  });
  const bm = trendAll();
  out.trend = Object.keys(bm).sort().map(k => [k, r2(bm[k])]);
  out.scheduled = SCHEDULED.map(t => t.id);
  return out;
}

/** What the phone's home-screen widget shows: the daily figure, what's left this month, the next payment and the
    balance curve until the salary after next. The app sends it whenever data loads; the server sends the same thing
    every hour (supabase/functions/device). Amounts are whole rupees; days count from today. */
function widgetModel(cards, h){
  if(!cards){ resolvePayments(); cards = allCards(); }
  h = h || heroModel(cards);
  const today = sod(new Date()), out = {v:1, at:Date.now(), day:iso(today), state:h.state};
  if(h.state !== "ok") return out;
  const R = Math.round, f = h.f, c = h.chart;
  out.daily = R(h.pace); out.line = h.line; out.tone = h.tone || "";
  out.left = R(h.tiles.rest.total); out.leftDays = h.tiles.rest.days; out.payday = iso(f.P1);
  out.bill = h.nextPay ? {title:h.nextPay.title, amt:R(h.nextPay.amt), due:iso(h.nextPay.d), n:days(today, h.nextPay.d), overdue:h.nextPay.overdue || 0} : null;
  out.curve = {span:Math.max(1, days(c.from, c.to)), buffer:R(c.buffer), pts:c.pts.map(p => [days(c.from, p.d), R(p.bal)]),
    paydays:c.paydays.map(d => days(c.from, d)), low:[days(c.from, c.low.d), R(c.low.bal)]};
  // for the bigger widget sizes: spent today, and the next few dated things (bills, transfers, the salary)
  out.spent = R(spendOf(txFor(ymOf(today)).filter(x => x.day === today.getDate())).spend);
  out.soon = comingUp(cards, f).flatMap(g => g.items.filter(e => !e.soft && e.amt !== null)
    .map(e => ({n:g.n, title:e.title, amt:R(e.amt), dot:e.dot}))).slice(0, 6);
  return out;
}

/** The 9 PM summary notification, in the app's own words. */
function digestModel(){
  resolvePayments();
  const cards = allCards(), h = heroModel(cards), n = netModel(cards), today = sod(new Date());
  const spent = spendOf(txFor(ymOf(today)).filter(x => x.day === today.getDate())).spend;
  const soon = h.f ? comingUp(cards, h.f).filter(g => g.n <= 3).flatMap(g => g.items.filter(e => !e.soft && e.amt !== null && e.dot !== "in")
    .map(e => ({n:g.n, text:e.title + " " + money(Math.abs(e.amt))}))) : [];
  const whenWord = k => k === 0 ? "today" : k === 1 ? "tomorrow" : "in " + k + " days";
  const title = h.state === "ok" ? money(h.tiles.rest.total) + " safe to spend until payday (" + money(h.pace) + " a day)" : "Money: today";
  const parts = ["Spent today " + money(spent) + "."];
  if(n) parts.push("Where you stand " + money(n.now) + ".");
  if(h.f && h.f.firstShort) parts.unshift(h.line + ".");             // the forecast sees a gap coming: say it first
  if(soon.length) parts.push("Coming up: " + soon.slice(0, 3).map(x => x.text + " " + whenWord(x.n)).join("; ") + ".");
  return {date:iso(today), title, body:parts.join(" ")};
}

/* =============================================================================================
   Actions: every change you can make. Each one updates the figures, redraws and saves.
   Those that can fail return a message to show (or "" when it worked).
   ============================================================================================= */
function render(){ resolvePayments(); hook("render"); }
function lightRender(){ resolvePayments(); hook("render", {light:true}); }   // while a slider is being dragged
const remote = (name, ...a) => {
  const f = window.MONEY && MONEY[name];
  if(typeof f !== "function") return Promise.resolve();
  return Promise.resolve(f(...a)).catch(e => { hook("toast", "Couldn't save that: " + (e && e.message || e), {tone:"alert"}); throw e; });
};
const todayISO = () => iso(sod(new Date()));
const isISO = s => /^\d{4}-\d{2}-\d{2}$/.test(s || "");

const act = {
  /* the salary planner */
  setPlan(k, v, light){
    const cyc = planCycleView(), o = Object.assign({}, planEdits(cyc));
    o[k] = Math.max(0, Math.round(v)); if(k === "sal") o.salAt = Date.now();
    overrides[planKey(cyc)] = o;
    if(light) lightRender(); else render();
    queueSave();
  },
  resetPlan(){ delete overrides[planKey(planCycleView())]; render(); queueSave(); },
  /** "cur" (the salary you're living on) or "next" (the coming one) on the Plan screen. */
  planView(v){ PLAN_VIEW = v === "next" || v === "cur" ? v : null; render(); },
  setSetting(k, v){
    if(k === "inc") settings.inc = v === "" || v === null ? null : (parseFloat(v) || 0);
    else if(k === "payDay"){ const n = parseInt(v, 10); settings.payDay = n >= 1 && n <= 31 ? n : 0; settings.payDayV = 1; }
    else if(k === "buffer") settings.buffer = Math.max(0, parseFloat(v) || 0);
    else if(k === "joined") settings.joined = isISO(v) ? v : "";
    else return;
    render(); queueSave();
  },
  /** k: a bank's key (your first bank when left out). */
  setBalance(v, k){
    const b = bankByKey(k) || BANKS[0];
    if(!b) return "Add your bank first.";
    v = parseFloat(v);
    if(!(v >= 0)) return "Enter the balance the " + b.name + " app shows right now.";
    settings[b.ob] = v; settings[b.at] = Date.now(); render(); queueSave(); return "";
  },

  /* goals */
  addGoal({name, target, start, date, prio}){
    name = String(name || "").trim(); target = parseFloat(target); start = parseFloat(start) || 0;
    if(!name) return "Give the goal a name.";
    if(!(target > 0)) return "Enter a target above zero.";
    if(!date || new Date(date + "T00:00:00") <= sod(new Date())) return "Pick a date in the future.";
    if(start < 0 || start > target) return "Already saved should be between zero and the target.";
    goals.push({id:"g" + Date.now(), name, target, start, date, prio:parseInt(prio, 10) || 2});
    render(); queueSave(); return "";
  },
  delGoal(id){ goals = goals.filter(g => g.id !== id); contribs = contribs.filter(c => c.goal !== id); render(); queueSave(); },
  addContrib(goal, amt, date){
    amt = parseFloat(amt);
    if(!(amt > 0)) return "Enter an amount above zero.";
    if(!isISO(date)) return "Pick the date you moved it.";
    contribs.push({id:"c" + Date.now(), goal, amt, date}); render(); queueSave(); return "";
  },
  delContrib(id){ contribs = contribs.filter(c => c.id !== id); render(); queueSave(); },

  /* payments you add yourself (things the alerts missed) */
  /** dir "in" for money you received (salary, from someone, paid back, a refund); out otherwise. */
  addManual({t, amt, c, date, acct, dir}){
    t = String(t || "").trim(); amt = parseFloat(amt);
    const inn = dir === "in";
    if(!(amt > 0)) return "Enter an amount above zero.";
    if(!t) return inn ? "Add who it's from or what it's for." : "Add a short description.";
    if(!isISO(date)) return inn ? "Pick the day it came in." : "Pick the day you paid.";
    const d = parseISO(date);
    const ok = inn ? IN_PICK.some(p => p[0] === c) : CATS.indexOf(c) >= 0;
    const m = {id:"m" + Date.now(), d:d.getDate(), t, amt, c:ok ? c : inn ? "Other income" : "Other", ym:ymOf(d)};
    if(inn) m.dir = "in";
    if(acct) m.acct = acct;
    if(date === todayISO()) m.ts = Date.now();
    manual.push(m); buildMonths(); render(); queueSave(); return "";
  },
  editManual(id, fields){
    const m = manual.find(x => x.id === id); if(!m) return;
    if(typeof fields.t === "string" && fields.t.trim()) m.t = fields.t.trim();
    if(fields.amt > 0) m.amt = +fields.amt;
    render(); queueSave();
  },
  delManual(id){ manual = manual.filter(m => m.id !== id); if(NOTES[id]) act.saveNote(id, null); buildMonths(); render(); queueSave(); },

  /* card payments */
  assignPayment(txId, v){ payAssign[txId] = v; render(); queueSave(); },
  notCardPayment(txId){ payAssign[txId] = "none"; render(); queueSave(); },
  addPayment(group, date, amt){
    amt = parseFloat(amt);
    if(!(amt > 0)) return "Enter an amount above zero.";
    if(!isISO(date)) return "Pick the date you paid.";
    payments.push({id:"p" + Date.now(), card:group, date, amt}); render(); queueSave(); return "";
  },
  delPayment(id){ payments = payments.filter(p => p.id !== id); render(); queueSave(); },
  setStatement(okey, amt){
    amt = parseFloat(amt);
    if(!(amt >= 0)) return "Enter the statement's total due.";
    overrides[okey] = amt; render(); queueSave(); return "";
  },
  clearStatement(okey){
    const [g, s] = okey.split("|");
    delete overrides[okey]; membersOf(g).forEach(m => delete overrides[m + "|" + s]);
    render(); queueSave();
  },

  /* salary & fixed payments */
  setCfg(next){ applyCfg(next); render(); queueSave(); },
  setCfgField(path, value){
    const c = cfgNow(), [a, b] = path.split(".");
    if(!c[a]) return;
    c[a][b] = value; act.setCfg(c);
  },
  addPlanned({name, amt, due, n, from}){
    name = String(name || "").trim(); amt = parseFloat(amt); n = Math.max(1, Math.min(60, parseInt(n, 10) || 1));
    if(!name) return "Say what it's for.";
    if(!(amt > 0)) return "Enter an amount above zero.";
    if(!isISO(due)) return "Pick the first date.";
    const c = cfgNow(), d0 = parseISO(due);
    for(let k = 0; k < n; k++){
      const d = onDay(d0.getFullYear(), d0.getMonth() + k, d0.getDate());
      c.planned.push({name:n > 1 ? name + " " + (k + 1) + " of " + n : name, amt, due:iso(d), from:from === "savings" ? "savings" : "pay", goal:""});
    }
    act.setCfg(c); return "";
  },
  delPlanned(i){ const c = cfgNow(); c.planned.splice(i, 1); act.setCfg(c); },
  useTakeHome(){ settings.inc = regularTakeHome(); render(); queueSave(); },
  resetCfg(){ act.setCfg(null); },
  /** Your banks and cards (see applyProfile). */
  setProfile(p){ applyProfile(p); TX = takeTx(TX.concat(SCHEDULED)); render(); queueSave(); },
  /** A setup brought in from a link or pasted text: {profile, cfg, rename}. The profile replaces yours; salary
      figures, rule and fixed payments only fill what you haven't set; rename moves saved planner choices that an
      earlier version kept under another name (e.g. {"share": "family"}) to the name used now. */
  importSetup(x){
    if(!x || typeof x !== "object" || !x.profile || typeof x.profile !== "object") return "That isn't a Money setup.";
    applyProfile(x.profile);
    TX = takeTx(TX.concat(SCHEDULED));                   // a card it says is closed drops its scheduled charges
    const ren = x.rename && typeof x.rename === "object" ? x.rename : {};
    const move = o => { if(o && typeof o === "object") Object.keys(ren).forEach(k => { if(k in o){ if(!(ren[k] in o)) o[ren[k]] = o[k]; delete o[k]; } }); };
    Object.keys(overrides).forEach(k => { if(/^plan\|/.test(k)) move(overrides[k]); });
    const c = cfg && typeof cfg === "object" ? JSON.parse(JSON.stringify(cfg)) : {};
    if(c.rule) move(c.rule);
    const add = x.cfg && typeof x.cfg === "object" ? x.cfg : {};
    ["offer", "rule"].forEach(k => { if(add[k] && typeof add[k] === "object") c[k] = Object.assign({}, add[k], c[k] || {}); });
    if(!Array.isArray(c.planned) && Array.isArray(add.planned)) c.planned = add.planned;
    applyCfg(Object.keys(c).length ? c : null);
    render(); queueSave(); return "";
  },

  /* your edits: payee rules and notes */
  setRule(desc, cat){
    const k = ruleKey(desc); if(!k) return;
    if(cat) catRules[k] = cat; else delete catRules[k];
    if(NOTES_OK) (cat ? remote("saveRule", k, cat) : remote("deleteRule", k)).catch(() => {});
    render(); queueSave();
  },
  delRule(pattern){
    delete catRules[pattern];
    if(NOTES_OK) remote("deleteRule", pattern).catch(() => {});
    render(); queueSave();
  },
  saveNote(id, row){
    const empty = !row || (!row.category && !row.for_someone_else && !row.paid_back && !String(row.note || "").trim());
    if(empty) delete NOTES[id]; else NOTES[id] = {category:row.category || null, for_someone_else:!!row.for_someone_else, paid_back:!!row.paid_back, note:String(row.note || "").trim()};
    return remote("saveNote", id, empty ? null : NOTES[id]);
  },
  /** The edit sheet's Save. e = {category, always, ruleWas, forOther, paidBack, note}.
      always: "Always use this for <payee>" (a payee rule); ruleWas: it was ticked when the sheet opened. */
  saveEdit(id, e){
    const t = TX.find(x => x.id === id), m = !t ? manual.find(x => x.id === id) : null;
    if(!t && !m) return "That transaction isn't there any more.";
    let category = null;
    if(t){
      const rule = ruleFor(t.desc);
      if(e.always && e.category){ if(!rule || rule.category !== e.category) act.setRule(t.desc, e.category); }
      else if(!e.always && e.ruleWas && rule) act.setRule(t.desc, null);
      // what it would be with no note of its own; a note is only kept when it says something different
      const had = NOTES[id]; delete NOTES[id];
      const base = withRules(t).cat;
      if(had) NOTES[id] = had;
      category = !e.always && e.category && e.category !== base ? e.category : null;
    } else if(e.category && CATS.indexOf(e.category) >= 0 && e.category !== m.c){ m.c = e.category; }
    if(m && typeof e.note === "string" && !NOTES_OK){ /* no table for notes yet: nothing to keep */ }
    if(!NOTES_OK){
      // before the edit tables exist: only rules and "paid back" can be kept (in the saved settings)
      if(t && t.dir === "in"){ const k = "paidback|" + id; if(e.paidBack) overrides[k] = true; else delete overrides[k]; }
      render(); queueSave(); return "";
    }
    const row = {category, for_someone_else:!!e.forOther && (!t || t.dir === "out"), paid_back:!!e.paidBack && !!t && t.dir === "in", note:e.note || ""};
    if(t && t.dir === "in"){ const k = "paidback|" + id; if(row.paid_back) overrides[k] = true; else delete overrides[k]; }   // a copy for the Sheet
    act.saveNote(id, row).catch(() => {});
    render(); queueSave(); return "";
  },
  refresh(){ return refresh(); },
};

/* ---------------- boot ---------------- */
function start(){
  const raw = lsGet(CACHE_KEY);
  if(raw){ try{ const v = JSON.parse(raw);
    if(v.profile) applyProfile(v.profile);
    if(Array.isArray(v.tx)) TX = takeTx(v.tx);
    if(Array.isArray(v.events)) EVENTS = v.events;
    applySettings(Object.assign({}, v.settings, {manual:v.manual, payments:v.payments, overrides:v.overrides,
      catRules:v.catRules, goals:v.goals, contribs:v.contribs, payAssign:v.payAssign, cfg:v.cfg, profile:v.profile}));
    if(v.notesOk){ NOTES_OK = true; NOTES = v.notes || {}; }
    lastRun = v.lastRun || null; lastFetch = v.at || null;
  }catch(e){} }
  buildMonths(); render();
  if(TX.length) setFeed("idle", "Emails checked " + ago(lastRun));
  load();
  setInterval(() => { if(!document.hidden && lastFetch && Date.now() - lastFetch > REFRESH_MS) load(); }, 5 * 60 * 1000);
  document.addEventListener("visibilitychange", () => { if(!document.hidden && lastFetch && Date.now() - lastFetch > 5 * 60 * 1000) load(); });
}

/* =============================================================================================
   Money · Trips on points.

   "How much do I have to spend, and on which card, to pay for a trip with points?" Pick a country, how many of you,
   how many nights and how comfortable; this works out the points the flights and the hotel cost, and for every card
   worth considering: how much spending earns them, how long that takes at your own spending, what it costs in fees,
   and whether your income clears the card's bar.

   It is loaded after engine.js and uses its names (settings, overrides, MONTHS, txFor, act, render, queueSave …).
   Nothing here is used by the server.

   TRIP_DATA is public information only: card terms, transfer ratios, award prices, hotel prices. Every number came
   from a published page and was checked on TRIP_DATA.checked; `src` names the page (TRIP_DATA.sources). Banks and
   airlines change these often, so the screens always show the date and say what could not be confirmed.

   How the points are counted
     Flights  the airline's own award price, one way per person, × 2 × travellers, in the class you pick. The
              preferred airline is the one that asks for fewer points: Air India (Maharaja Club) or Singapore
              Airlines (KrisFlyer); you can pick the other. Taxes and airport fees on award tickets are paid in
              cash and are not counted.
     Cards    ranked for that airline by conversion: the airline points ₹100 of everyday spending turns into
              (what the card earns ÷ how many of its points make one airline point), whatever your income.
     Hotel    Accor (ibis, Novotel, Mercure, Pullman, Sofitel, Fairmont …): 2,000 points take €40 off any stay, so
              the price in points follows the room price. Rooms = one for every two travellers.
     A card   earns points on everyday spending and more on flights and hotels; some spending earns nothing (fuel,
              bills, rent, insurance, fees, taxes, wallet loads). Welcome and milestone points are counted in the
              month they would arrive; the yearly fee (with 18% GST) is counted unless spending waives it.
   ============================================================================================= */
